((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).en = window.CARDS_BY_LANG.en || {}).person = [{"name":"Leonardo DiCaprio","emoji":"🚢","meta":["actor","United States","1974"],"description":"One of the most recognisable actors in Hollywood today, made famous by \"Titanic\" and \"The Wolf of Wall Street\". His Oscar came for \"The Revenant\", as a frontiersman fighting to stay alive in the wilderness. He puts serious money and time into environmental causes.","fact":"He was nominated several times before he finally won his first Oscar, and the long wait turned into a running internet joke.","wiki_en":"Leonardo DiCaprio"},{"name":"Brad Pitt","emoji":"🎰","meta":["actor, producer","United States","1963"],"description":"A Hollywood actor and producer known for \"Fight Club\", \"Se7en\" and \"Once Upon a Time in Hollywood\", which brought him an acting Oscar. He has a second statuette as a producer, for \"12 Years a Slave\".","fact":"Early on, before films worked out for him, he took odd promotional jobs that involved wearing costumes.","wiki_en":"Brad Pitt"},{"name":"Angelina Jolie","emoji":"🏹","meta":["actress, director","United States","1975"],"description":"An actress and director who won an Oscar for \"Girl, Interrupted\". She is known as Lara Croft and as the villain Maleficent, and for years of work as a UN goodwill ambassador for refugees.","fact":"Her father is the actor Jon Voight, an Oscar winner himself, so father and daughter each have a statuette.","wiki_en":"Angelina Jolie"},{"name":"Tom Cruise","emoji":"✈️","meta":["actor","United States","1962"],"description":"One of Hollywood's leading action stars, known for the \"Mission: Impossible\" franchise and \"Top Gun\". He is famous for insisting on performing his own difficult and dangerous stunts rather than handing them to a double.","fact":"He holds a pilot's licence and flies the aircraft that appear in his films himself.","wiki_en":"Tom Cruise"},{"name":"Johnny Depp","emoji":"🏴‍☠️","meta":["actor","United States","1963"],"description":"An actor who made his name with eccentric roles: Captain Jack Sparrow in \"Pirates of the Caribbean\" and a string of characters in Tim Burton's films, among them \"Edward Scissorhands\".","fact":"He came up with much of Jack Sparrow himself, borrowing the character's manner from the musician Keith Richards.","wiki_en":"Johnny Depp"},{"name":"Robert Downey Jr.","emoji":"🦾","meta":["actor","United States","1965"],"description":"The actor known worldwide as Tony Stark, the Iron Man of the Marvel Cinematic Universe and the role that held that whole run of films together. He also won an Oscar for his performance in \"Oppenheimer\".","fact":"Tony Stark lifted his career to a new level after a rough stretch in his life that he has spoken about openly many times.","wiki_en":"Robert Downey Jr."},{"name":"Will Smith","emoji":"🕶️","meta":["actor, musician","United States","1968"],"description":"An actor and rapper who started out on the sitcom \"The Fresh Prince of Bel-Air\", then became one of Hollywood's biggest box-office draws with \"Men in Black\" and \"I Am Legend\". His Oscar came for \"King Richard\".","fact":"Before acting he performed as a rapper and took one of the first Grammys ever awarded in a hip-hop category.","wiki_en":"Will Smith"},{"name":"Tom Hanks","emoji":"🏐","meta":["actor","United States","1956"],"description":"One of the most respected actors in Hollywood, he won the Oscar two years running, for \"Philadelphia\" and \"Forrest Gump\". He is also known for \"Saving Private Ryan\" and as the voice of Woody in \"Toy Story\".","fact":"He is one of very few actors in history to win the Oscar for a leading role in two consecutive years.","wiki_en":"Tom Hanks"},{"name":"Morgan Freeman","emoji":"📖","meta":["actor","United States","1937"],"description":"An actor with an unmistakable deep voice, known for \"The Shawshank Redemption\" and an Oscar winner for \"Million Dollar Baby\". That voice is regularly hired to narrate documentaries.","fact":"His voice is so recognisable that he is often asked to narrate documentaries about nature and the universe.","wiki_en":"Morgan Freeman"},{"name":"Denzel Washington","emoji":"🎖️","meta":["actor","United States","1954"],"description":"One of the few Black actors to have won the Oscar twice, taking it for \"Glory\" and then for \"Training Day\". He is also known for the title role in \"Malcolm X\" and for his long-running work with the director Spike Lee.","fact":"He often returns to the stage and has played on Broadway, including Brutus in \"Julius Caesar\".","wiki_en":"Denzel Washington"},{"name":"Keanu Reeves","emoji":"💊","meta":["actor","Canada","1964"],"description":"The Canadian actor known for \"The Matrix\" trilogy and the \"John Wick\" franchise. Inside the industry and among fans alike he has a reputation as one of the most modest and good-natured people in Hollywood.","fact":"He is keen on motorcycles and co-founded his own company building custom bikes.","wiki_en":"Keanu Reeves"},{"name":"Dwayne Johnson","emoji":"💪","meta":["actor","United States","1972"],"description":"A former professional wrestler who fought under the name The Rock and is now one of the highest-paid actors in Hollywood, thanks above all to the \"Fast & Furious\" and \"Jumanji\" films.","fact":"Before he became an actor he spent years as a star of the WWE wrestling league.","wiki_en":"Dwayne Johnson"},{"name":"Arnold Schwarzenegger","emoji":"🤖","meta":["actor, politician","United States","1947"],"description":"An Austrian-born actor who became famous through \"The Terminator\" and \"Predator\", and was later elected governor of California. Before films he made his name in bodybuilding, winning the Mr. Olympia title several times.","fact":"His line \"I'll be back\" from \"The Terminator\" is one of the most quoted in the history of cinema.","wiki_en":"Arnold Schwarzenegger"},{"name":"Sylvester Stallone","emoji":"🥊","meta":["actor, screenwriter","United States","1946"],"description":"An actor and screenwriter who created and starred in the \"Rocky\" and \"Rambo\" franchises, the defining action films of the 1970s and 1980s. Later he gathered the genre's biggest names into \"The Expendables\", again writing as well as acting.","fact":"He wrote the first \"Rocky\" script himself in a matter of days and insisted on playing the lead.","wiki_en":"Sylvester Stallone"},{"name":"Jackie Chan","emoji":"🥋","meta":["actor","Hong Kong","1954"],"description":"The Hong Kong actor and stuntman who made his name by mixing martial arts with comic timing and elaborate stunt work, in films such as \"Police Story\" and the \"Rush Hour\" series, where the fights are played for laughs as much as for thrills.","fact":"He is known for preferring to do most of his own stunts, which has left him injured on set more than once.","wiki_en":"Jackie Chan"},{"name":"Bruce Lee","emoji":"🐉","meta":["actor, martial artist","United States","1940–1973"],"description":"An actor and martial artist who did more than anyone else to make kung fu known to Western audiences. He starred in \"Enter the Dragon\" and \"Fist of Fury\" and founded his own style, Jeet Kune Do.","fact":"As a teenager in Hong Kong he won the city's cha-cha dancing championship.","wiki_en":"Bruce Lee"},{"name":"Jim Carrey","emoji":"🎭","meta":["actor","Canada","1962"],"description":"The Canadian comic actor known for his rubber face and full-body clowning in \"The Mask\", \"Dumb and Dumber\" and \"Eternal Sunshine of the Spotless Mind\". He started out in stand-up and television sketch comedy.","fact":"Beyond comedy he has proved himself a dramatic actor more than once, in \"The Truman Show\" above all.","wiki_en":"Jim Carrey"},{"name":"Adam Sandler","emoji":"🏌️","meta":["actor","United States","1966"],"description":"A comic actor and screenwriter who got his start on the sketch show \"Saturday Night Live\" and then headlined a long run of popular comedies, among them \"Happy Gilmore\" and \"Grown Ups\".","fact":"He is also known for a long partnership with Netflix, where he has made a whole series of his own comedies.","wiki_en":"Adam Sandler"},{"name":"Ryan Reynolds","emoji":"🔫","meta":["actor","Canada","1976"],"description":"The Canadian actor who became widely known as the wisecracking superhero of the \"Deadpool\" films. He is also known as a businessman and for advertising campaigns built on making fun of himself.","fact":"He co-owns the football club Wrexham, whose revival was turned into a documentary series.","wiki_en":"Ryan Reynolds"},{"name":"Ryan Gosling","emoji":"🚗","meta":["actor","Canada","1980"],"description":"A Canadian actor who began on a Disney children's show and went on to \"The Notebook\", \"Drive\" and the musical \"La La Land\", which brought him an Oscar nomination. Later he played Ken in \"Barbie\".","fact":"He started out as a child performer on \"The Mickey Mouse Club\", alongside future pop stars.","wiki_en":"Ryan Gosling"},{"name":"Chris Hemsworth","emoji":"🔨","meta":["actor","Australia","1983"],"description":"The Australian actor known as Thor in the Marvel Cinematic Universe, a part that has followed him through more than a decade of films. Before Hollywood he spent several years working in Australian television series.","fact":"He landed Thor after several years in Australian series, including the soap \"Home and Away\".","wiki_en":"Chris Hemsworth"},{"name":"Hugh Jackman","emoji":"🐺","meta":["actor","Australia","1968"],"description":"The Australian actor who played Wolverine in the X-Men films for more than fifteen years. He is just as well known for musicals, singing and dancing his way through \"The Greatest Showman\".","fact":"He is equally at home in film and on Broadway, where he has starred in musicals and hosted the Tony Awards several times.","wiki_en":"Hugh Jackman"},{"name":"Matthew McConaughey","emoji":"🤙","meta":["actor","United States","1969"],"description":"An actor who won the Oscar for \"Dallas Buyers Club\", and who is just as well remembered for the television series \"True Detective\" and for a stack of romantic comedies through the 2000s.","fact":"For \"Dallas Buyers Club\" he lost a great deal of weight to play a character living with AIDS more convincingly.","wiki_en":"Matthew McConaughey"},{"name":"Joaquin Phoenix","emoji":"🃏","meta":["actor","United States","1974"],"description":"An actor known for intense dramatic parts, who won the Oscar for the title role in \"Joker\". Earlier he appeared in \"Gladiator\" and in \"Walk the Line\", the biopic about Johnny Cash.","fact":"For \"Joker\" he lost a lot of weight, aiming to convey how physically frail and broken the character is.","wiki_en":"Joaquin Phoenix"},{"name":"Christian Bale","emoji":"🦇","meta":["actor","United Kingdom","1974"],"description":"The British actor known as Bruce Wayne in Christopher Nolan's Batman trilogy, and just as much for his willingness to change his weight and his whole appearance beyond recognition for a role.","fact":"He has repeatedly transformed his body for parts, starving himself thin for some and packing on muscle for others.","wiki_en":"Christian Bale"},{"name":"Al Pacino","emoji":"🚬","meta":["actor","United States","1940"],"description":"The actor who became famous as Michael Corleone in \"The Godfather\" trilogy and won his Oscar for \"Scent of a Woman\". He is also known for the crime dramas \"Scarface\" and \"Heat\", which put him on screen with Robert De Niro for the first time.","fact":"The studio originally wanted another actor as Michael Corleone; the stubbornness of the director, Coppola, changed everything.","wiki_en":"Al Pacino"},{"name":"Robert De Niro","emoji":"🚕","meta":["actor","United States","1943"],"description":"One of the most decorated actors of his generation, known above all for his long collaboration with the director Martin Scorsese on \"Taxi Driver\" and \"Goodfellas\". He has won the Oscar twice.","fact":"To play the boxer in \"Raging Bull\" he put on a great deal of weight, matching the shape the character is in late in his career.","wiki_en":"Robert De Niro"},{"name":"Jack Nicholson","emoji":"🪓","meta":["actor","United States","1937"],"description":"An actor known for \"One Flew Over the Cuckoo's Nest\", \"The Shining\" and \"Batman\", with three acting Oscars to his name. His terrifying grin as the madman of \"The Shining\" became one of the most recognisable images in horror.","fact":"He is one of very few actors to have won the Oscar for both a leading and a supporting role.","wiki_en":"Jack Nicholson"},{"name":"Anthony Hopkins","emoji":"🍷","meta":["actor","United Kingdom","1937"],"description":"The British actor who became known worldwide as Hannibal Lecter, the imprisoned cannibal psychiatrist of \"The Silence of the Lambs\", a part that won him an Oscar. He took a second statuette much later, for \"The Father\".","fact":"His screen time in \"The Silence of the Lambs\" is very short, and yet the part won him the Oscar for a leading role.","wiki_en":"Anthony Hopkins"},{"name":"Samuel L. Jackson","emoji":"🐍","meta":["actor","United States","1948"],"description":"One of the most prolific actors in Hollywood, known for Quentin Tarantino's \"Pulp Fiction\" and \"Django Unchained\", and for playing Nick Fury, the man who assembles the heroes, across the Marvel films.","fact":"Counting the total box office of the films he has appeared in, he ranks among the highest-grossing actors in cinema history.","wiki_en":"Samuel L. Jackson"},{"name":"Quentin Tarantino","emoji":"💼","meta":["director","United States","1963"],"description":"A director and screenwriter known for non-linear storytelling, showy dialogue and loving pastiche of genre cinema: \"Pulp Fiction\", \"Kill Bill\", \"Once Upon a Time in Hollywood\", where long stretches are simply people talking.","fact":"He has said more than once that he plans to make only ten features in his career and then stop directing.","wiki_en":"Quentin Tarantino"},{"name":"Steven Spielberg","emoji":"🦈","meta":["director","United States","1946"],"description":"One of the most influential directors in the history of cinema. He made \"Jaws\", \"E.T.\", \"Schindler's List\" and \"Saving Private Ryan\", moving between blockbusters and heavy historical drama, and has twice won the Oscar for directing.","fact":"\"Jaws\" is considered one of the first summer blockbusters, and it set the fashion for huge cinema openings.","wiki_en":"Steven Spielberg"},{"name":"Christopher Nolan","emoji":"⏳","meta":["director","United Kingdom","1970"],"description":"The British director known for intricate plot structures and practical effects, in \"Inception\", \"Interstellar\" and his Batman trilogy. He won the Oscar for directing \"Oppenheimer\".","fact":"He prefers to shoot on film and to use real sets and stunts rather than computer graphics wherever he can.","wiki_en":"Christopher Nolan"},{"name":"Martin Scorsese","emoji":"🎥","meta":["director","United States","1942"],"description":"One of the central directors of the New Hollywood generation, he made \"Taxi Driver\", \"Goodfellas\" and \"The Departed\", the last of which brought him the Oscar for directing. Crime, guilt and New York run through almost all of it.","fact":"He was nominated for the directing Oscar for years and needed several attempts before the statuette finally came.","wiki_en":"Martin Scorsese"},{"name":"James Cameron","emoji":"🌊","meta":["director","Canada","1954"],"description":"The Canadian director behind the two highest-grossing films in cinema history, \"Titanic\" and \"Avatar\", as well as the \"Terminator\" franchise. He is known for chasing new filming technology and for setting up his own effects studios.","fact":"He is a keen deep-sea diver and personally made a record solo dive to the bottom of the Mariana Trench.","wiki_en":"James Cameron"},{"name":"Marilyn Monroe","emoji":"💋","meta":["actress","United States","1926–1962"],"description":"An actress and the sex symbol of Hollywood's golden age, she starred in the comedies \"Gentlemen Prefer Blondes\" and \"Some Like It Hot\" and became one of the most recognisable figures in twentieth-century pop culture.","fact":"The scene in \"The Seven Year Itch\" where her dress billows up over a subway grate is one of the best-known shots in film history.","wiki_en":"Marilyn Monroe"},{"name":"Audrey Hepburn","emoji":"💎","meta":["actress","United Kingdom","1929–1993"],"description":"The actress who became a byword for elegance through \"Breakfast at Tiffany's\" and \"Roman Holiday\", winning an Oscar for the latter. In her later years she devoted herself to work as a UNICEF goodwill ambassador.","fact":"The black dress she wears at the start of \"Breakfast at Tiffany's\" became one of the most famous costumes in film history.","wiki_en":"Audrey Hepburn"},{"name":"Charlie Chaplin","emoji":"🎩","meta":["actor, director","United Kingdom","1889–1977"],"description":"An actor, director and composer of the silent era, he created the Tramp, the little man in a bowler hat with a cane. He directed and played the lead in \"The Gold Rush\" and \"Modern Times\".","fact":"In 1972 he received an honorary Oscar, travelling to the United States for the first time in twenty years to collect it.","wiki_en":"Charlie Chaplin"},{"name":"Meryl Streep","emoji":"👗","meta":["actress","United States","1949"],"description":"The actress with more Oscar nominations than anyone else in the history of the Academy, known for \"The Devil Wears Prada\" and \"Kramer vs. Kramer\". She moves between comedy and heavy drama with equal ease, which is part of why the nominations keep coming.","fact":"She has three Oscars: for \"Kramer vs. Kramer\", \"Sophie's Choice\" and \"The Iron Lady\".","wiki_en":"Meryl Streep"},{"name":"Julia Roberts","emoji":"😁","meta":["actress","United States","1967"],"description":"The actress who became one of the highest-paid stars in Hollywood in the 1990s on the strength of \"Pretty Woman\", and who won the Oscar for \"Erin Brockovich\". Romantic comedy was her home ground for a whole decade.","fact":"Her smile became so recognisable that journalists regularly write about it as part of her screen image.","wiki_en":"Julia Roberts"},{"name":"Scarlett Johansson","emoji":"🕸️","meta":["actress","United States","1984"],"description":"One of the highest-paid actresses in the world, known as Black Widow in the Marvel Cinematic Universe and for dramatic work such as \"Marriage Story\". She moves between enormous franchises and small independent films.","fact":"Taken together, the films she has appeared in are among the highest-grossing of any actress in cinema history.","wiki_en":"Scarlett Johansson"},{"name":"Jennifer Lawrence","emoji":"🎯","meta":["actress","United States","1990"],"description":"The actress who became widely known as Katniss Everdeen in \"The Hunger Games\" franchise. Her Oscar came for \"Silver Linings Playbook\", making her one of the youngest winners in that category.","fact":"Her first Oscar nomination came before \"The Hunger Games\", for the independent drama \"Winter's Bone\".","wiki_en":"Jennifer Lawrence"},{"name":"Margot Robbie","emoji":"💗","meta":["actress","Australia","1990"],"description":"The Australian actress and producer known as Harley Quinn in the films of the DC universe, and as the lead in \"Barbie\", which became one of the biggest box-office successes of her career.","fact":"\"Barbie\", which she starred in, became one of the highest-grossing films ever directed by a woman.","wiki_en":"Margot Robbie"},{"name":"Emma Watson","emoji":"📚","meta":["actress","United Kingdom","1990"],"description":"The British actress who became famous worldwide as a child, as Hermione Granger in the Harry Potter films. She later finished university and took up campaigning for gender equality.","fact":"She served as a UN goodwill ambassador for gender equality and fronted the HeForShe campaign.","wiki_en":"Emma Watson"},{"name":"Emma Stone","emoji":"🎹","meta":["actress","United States","1988"],"description":"The actress who has twice won the Oscar for a leading role, for the musical \"La La Land\" and for \"Poor Things\". She started out in teen comedies such as \"Easy A\" before moving on to far stranger material.","fact":"She is one of very few actresses of the twenty-first century to have won two Oscars for a leading role.","wiki_en":"Emma Stone"},{"name":"Natalie Portman","emoji":"🦢","meta":["actress","United States","1981"],"description":"The actress who began appearing in films as a teenager, in \"Léon\", and later won the Oscar for the psychological drama \"Black Swan\". She is also known for her role in the \"Star Wars\" prequels.","fact":"Alongside her acting career she graduated from Harvard University with a degree in psychology.","wiki_en":"Natalie Portman"},{"name":"Nicole Kidman","emoji":"🌹","meta":["actress","Australia","1967"],"description":"The Australian actress who won the Oscar for playing the writer Virginia Woolf in \"The Hours\", and who is also known for \"Moulin Rouge!\" and the series \"Big Little Lies\". She has kept working steadily in both film and television.","fact":"For Virginia Woolf in \"The Hours\" a prosthetic nose changed her face almost beyond recognition.","wiki_en":"Nicole Kidman"},{"name":"Sandra Bullock","emoji":"🚌","meta":["actress","United States","1964"],"description":"The actress who became widely known after the action film \"Speed\", and won the Oscar for the drama \"The Blind Side\". She also starred in \"Gravity\", one of the most successful space thrillers ever made.","fact":"\"Gravity\" was shot almost entirely as though the action were taking place in the weightlessness of open space.","wiki_en":"Sandra Bullock"},{"name":"Jennifer Aniston","emoji":"☕","meta":["actress","United States","1969"],"description":"The actress who became known around the world as Rachel Green in the hugely popular sitcom \"Friends\", and who went on to a successful career in both film and television after the show ended.","fact":"Her character's haircut on \"Friends\" became one of the most copied women's hairstyles in the world at the time.","wiki_en":"Jennifer Aniston"},{"name":"Zendaya","emoji":"🏜️","meta":["actress, singer","United States","1996"],"description":"An actress and singer who started out on the Disney Channel and later made her name in the series \"Euphoria\" and in the \"Dune\" and \"Spider-Man\" franchises. She has also released music and appeared in the musical \"The Greatest Showman\".","fact":"\"Euphoria\" made her one of the youngest actresses ever to win the Emmy for a leading role in a drama.","wiki_en":"Zendaya"},{"name":"Timothée Chalamet","emoji":"🎸","meta":["actor","United States","1995"],"description":"The actor who came to wide attention with the drama \"Call Me by Your Name\", and later took leading roles in the \"Dune\" franchise and in a biopic about Bob Dylan. In a few years he went from small independent films to the largest productions in Hollywood.","fact":"He was nominated for a leading-role Oscar at twenty-two, among the youngest nominees ever in that category.","wiki_en":"Timothée Chalamet"},{"name":"Tom Holland","emoji":"🕷️","meta":["actor","United Kingdom","1996"],"description":"The British actor best known as Peter Parker, the Spider-Man of the Marvel Cinematic Universe. He began his career as a dancer, in the stage musical \"Billy Elliot\", and that training still shows in how he moves.","fact":"He first played Spider-Man not in a film of his own but in \"Captain America: Civil War\".","wiki_en":"Tom Holland (actor)"},{"name":"Pedro Pascal","emoji":"🛡️","meta":["actor","United States","1975"],"description":"The Chilean-born actor who became widely known through the series \"Game of Thrones\", \"The Mandalorian\" and \"The Last of Us\". Before those he spent many years playing supporting parts on American television.","fact":"In \"The Mandalorian\" his face is hidden under a helmet almost the whole time, which became the character's signature.","wiki_en":"Pedro Pascal"},{"name":"Benedict Cumberbatch","emoji":"🔮","meta":["actor","United Kingdom","1976"],"description":"The British actor who made his name as Sherlock Holmes in the BBC series \"Sherlock\", and as Doctor Strange in the Marvel films. Before that he worked extensively on the British stage and in BBC television films.","fact":"He voiced the dragon Smaug in \"The Hobbit\" trilogy, recorded using motion-capture technology.","wiki_en":"Benedict Cumberbatch"},{"name":"Daniel Radcliffe","emoji":"⚡","meta":["actor","United Kingdom","1989"],"description":"The British actor who became famous worldwide as a child, in the title role of the Harry Potter films, a series that took up most of his youth. Afterwards he turned to unusual independent projects.","fact":"Once the Harry Potter films were over he deliberately chose odd roles, to get away from the image of the boy wizard.","wiki_en":"Daniel Radcliffe"},{"name":"Cillian Murphy","emoji":"☢️","meta":["actor","Ireland","1976"],"description":"The Irish actor who worked with the director Christopher Nolan for many years, and who won the Oscar for the leading role in \"Oppenheimer\", the biopic about the man who built the atomic bomb.","fact":"On television his breakthrough was the lead in the British series \"Peaky Blinders\".","wiki_en":"Cillian Murphy"},{"name":"Milla Jovovich","emoji":"🧟","meta":["actress, model","United States","1975"],"description":"The actress and model, born in Kyiv, who became widely known as the lead in the \"Resident Evil\" films, adapted from the video games. She carried that franchise through a whole string of sequels.","fact":"Before acting she was an in-demand model and appeared in major fashion magazines while still very young.","wiki_en":"Milla Jovovich"},{"name":"Mila Kunis","emoji":"📺","meta":["actress","United States","1983"],"description":"The actress, born in Chernivtsi, who started out in the sitcom \"That '70s Show\" and as the voice of Meg in the animated series \"Family Guy\", and who later appeared in the drama \"Black Swan\".","fact":"She has voiced Meg Griffin on \"Family Guy\" for more than two decades, joining the show soon after it began.","wiki_en":"Mila Kunis"},{"name":"Kim Kardashian","emoji":"📸","meta":["media personality, entrepreneur","United States","1980"],"description":"A media personality and businesswoman who became known through the reality show \"Keeping Up with the Kardashians\", and who later built a successful business in underwear and cosmetics.","fact":"She founded the shapewear brand SKIMS, which became a notable player in the underwear market.","wiki_en":"Kim Kardashian"},{"name":"Kylie Jenner","emoji":"💄","meta":["entrepreneur","United States","1997"],"description":"A businesswoman and media personality from the Kardashian-Jenner family, she founded the cosmetics brand Kylie Cosmetics, which became one of the better-known names on the make-up market.","fact":"A large stake in her cosmetics brand was later bought by the international beauty company Coty.","wiki_en":"Kylie Jenner"},{"name":"Paris Hilton","emoji":"💅","meta":["media personality, entrepreneur","United States","1981"],"description":"A media personality, DJ and businesswoman, heiress to the Hilton hotel empire. In the 2000s she was among the first celebrities to become famous through reality television and the tabloids.","fact":"Her 2000s reality show \"The Simple Life\" was one of the first loud examples of celebrity reality TV.","wiki_en":"Paris Hilton"},{"name":"Oprah Winfrey","emoji":"🎙️","meta":["television host, media mogul","United States","1954"],"description":"A television host and media mogul who for many years presented one of the most popular talk shows on American television, \"The Oprah Winfrey Show\", and later founded her own channel, OWN.","fact":"Her talk show ran for several decades and became one of the most influential television projects in American history.","wiki_en":"Oprah Winfrey"},{"name":"Jimmy Fallon","emoji":"🌙","meta":["television host, comedian","United States","1974"],"description":"A television host and comedian, formerly a cast member of \"Saturday Night Live\", who now presents the popular late-night programme \"The Tonight Show\" on NBC, where games with guests matter as much as interviews.","fact":"Before he took over \"The Tonight Show\" he spent several years hosting another late-night show on the same network.","wiki_en":"Jimmy Fallon"},{"name":"MrBeast","emoji":"💰","meta":["YouTuber, entrepreneur","United States","1998"],"description":"The American YouTuber known for enormous, expensive videos full of challenges and huge cash prizes. His channel is one of the most popular in the world, and each new video tends to be built around a more extravagant idea than the last.","fact":"His real name is Jimmy Donaldson, and he came up with the name MrBeast before his channel became popular.","wiki_en":"MrBeast"},{"name":"PewDiePie","emoji":"🎮","meta":["YouTuber","Sweden","1989"],"description":"The Swedish video blogger whose real name is Felix Kjellberg. For years he was one of the most-subscribed creators on YouTube, on the strength of gaming videos and comedy sketches shot in front of a webcam.","fact":"For a long stretch his channel held the title of the most-subscribed individual channel on YouTube.","wiki_en":"PewDiePie"},{"name":"Gordon Ramsay","emoji":"🔪","meta":["chef, television host","United Kingdom","1966"],"description":"The British chef with several Michelin stars, just as well known for his abrasive television shows \"Hell's Kitchen\" and \"Kitchen Nightmares\", where a good deal of the drama comes from him shouting at the cooking.","fact":"As a young man he played football seriously, but a knee injury forced him to give that career up.","wiki_en":"Gordon Ramsay"},{"name":"Elon Musk","emoji":"🚀","meta":["entrepreneur","United States","1971"],"description":"The South African-born entrepreneur who founded and runs Tesla and SpaceX, and who co-owns the social network X, formerly known as Twitter. One of the most visible and most argued-about figures in world business of recent years.","fact":"SpaceX, the company he founded, became the first private firm to send people into orbit aboard its own spacecraft.","wiki_en":"Elon Musk"},{"name":"Bill Gates","emoji":"🪟","meta":["entrepreneur","United States","1955"],"description":"One of the founders of Microsoft, he played a key part in the rise of the personal computer and of the software business. These days he works on philanthropy through his own foundation.","fact":"He dropped out of Harvard in order to concentrate on building Microsoft.","wiki_en":"Bill Gates"},{"name":"Steve Jobs","emoji":"🍎","meta":["entrepreneur","United States","1955–2011"],"description":"Co-founder of Apple, present at the birth of the Macintosh personal computer and, after his return to the company, the man who drove the development of the iPod, iPhone and iPad, the devices that turned Apple into a household name.","fact":"He left Apple in the mid-1980s after falling out with the management, and came back more than a decade later to run it.","wiki_en":"Steve Jobs"},{"name":"Mark Zuckerberg","emoji":"📘","meta":["entrepreneur","United States","1984"],"description":"Co-founder and head of Meta, formerly known as Facebook. He launched the social network while he was a student at Harvard and turned it into one of the largest technology companies in the world.","fact":"He launched Facebook from a dormitory at Harvard University, where he was studying at the time.","wiki_en":"Mark Zuckerberg"},{"name":"Jeff Bezos","emoji":"📦","meta":["entrepreneur","United States","1964"],"description":"The founder of Amazon, who turned a small online bookshop into one of the largest companies in the world and a giant of e-commerce. He also founded the space company Blue Origin, his own way into the rocket business.","fact":"He started Amazon by selling books over the internet, working out of his own garage.","wiki_en":"Jeff Bezos"},{"name":"Pavel Durov","emoji":"📨","meta":["entrepreneur","Russia","1984"],"description":"The entrepreneur who founded the social network VKontakte and then the messenger Telegram, which has become one of the most popular ways of talking to people anywhere in the world.","fact":"After selling his stake in VKontakte he concentrated on Telegram, funding it at first out of his own pocket.","wiki_en":"Pavel Durov"},{"name":"David Beckham","emoji":"🎯","meta":["footballer","United Kingdom","1975"],"description":"A former footballer, a midfielder who played for Manchester United, Real Madrid and the England national team, known for his pinpoint passing and for free kicks he could bend around any wall.","fact":"The title of the film \"Bend It Like Beckham\" is a nod to his famous free kicks.","wiki_en":"David Beckham"},{"name":"Cristiano Ronaldo","emoji":"🐐","meta":["footballer","Portugal","1985"],"description":"The Portuguese footballer, one of the most prolific goalscorers in the history of the game, who has played for Manchester United and Real Madrid among others, and who led the Portugal national team for many years.","fact":"He is one of very few footballers to have scored more than a hundred goals for his national team.","wiki_en":"Cristiano Ronaldo"},{"name":"Lionel Messi","emoji":"🥇","meta":["footballer","Argentina","1987"],"description":"The Argentine footballer who was the face of Barcelona for many years and holds a record number of Ballon d'Or awards. In 2022 he led the Argentina national team to victory at the World Cup.","fact":"In 2022 he finally won the World Cup with Argentina, the one trophy still missing from his collection.","wiki_en":"Lionel Messi"},{"name":"Neymar","emoji":"🎪","meta":["footballer","Brazil","1992"],"description":"The Brazilian footballer behind one of the most expensive transfers in the history of the game, who has played for Barcelona and Paris Saint-Germain and is known for a technical, showy style.","fact":"His move from Barcelona to Paris Saint-Germain remained one of the most expensive transfers in football for years.","wiki_en":"Neymar"},{"name":"Pelé","emoji":"🏆","meta":["footballer","Brazil","1940–2022"],"description":"The Brazilian footballer who won the World Cup three times with Brazil, and whom many consider one of the greatest players ever to touch a ball. His name became shorthand for football itself far beyond Brazil.","fact":"He remains the only footballer to have won the World Cup three times with the same national team.","wiki_en":"Pelé"},{"name":"Diego Maradona","emoji":"✋","meta":["footballer","Argentina","1960–2020"],"description":"The Argentine footballer who led his country to victory at the 1986 World Cup, and who is also remembered for a spectacular spell at the Italian club Napoli, where he is still treated as a local saint.","fact":"At the 1986 World Cup he scored a goal he himself called the \"Hand of God\", and the argument about it has lasted for decades.","wiki_en":"Diego Maradona"},{"name":"Zinedine Zidane","emoji":"🌪️","meta":["footballer, manager","France","1972"],"description":"The French footballer of Algerian descent who won the 1998 World Cup, and who later became a successful manager, taking Real Madrid to several Champions League titles in a row, an unusual second act for a star player.","fact":"In the 1998 World Cup final he scored twice with his head in the match against Brazil.","wiki_en":"Zinedine Zidane"},{"name":"Kylian Mbappé","emoji":"⚡","meta":["footballer","France","1998"],"description":"The French footballer, one of the fastest and most prolific forwards in the game today, who won the 2018 World Cup with France while still a teenager. Defenders tend to mention his acceleration first.","fact":"At the 2018 World Cup he became one of the youngest footballers ever to score in a final.","wiki_en":"Kylian Mbappé"},{"name":"Michael Jordan","emoji":"👟","meta":["basketball player","United States","1963"],"description":"The legendary basketball player, six times an NBA champion with the Chicago Bulls, whom many consider the greatest ever to play the game. After retiring as a player he became the owner of an NBA club.","fact":"With his Air Jordan sneaker brand he became one of the most influential figures in the history of sports marketing.","wiki_en":"Michael Jordan"},{"name":"LeBron James","emoji":"👑","meta":["basketball player","United States","1984"],"description":"One of the most decorated basketball players of the modern era, an NBA champion with several different clubs and one of the league's all-time leaders in career points scored, over a career that has already lasted more than two decades.","fact":"He is one of very few NBA players to have won the championship with three different clubs.","wiki_en":"LeBron James"},{"name":"Kobe Bryant","emoji":"🐍","meta":["basketball player","United States","1978–2020"],"description":"The basketball player who spent his entire career with the Los Angeles Lakers, a five-time NBA champion, known for an extraordinary work ethic and for the nickname Black Mamba. For two decades he was the face of the club.","fact":"He described his trademark work ethic as the \"Mamba mentality\", a phrase that caught on well beyond basketball.","wiki_en":"Kobe Bryant"},{"name":"Shaquille O'Neal","emoji":"🏀","meta":["basketball player","United States","1972"],"description":"One of the most physically dominant centres in NBA history, a champion with the Los Angeles Lakers and the Miami Heat. His height and sheer strength made him almost impossible to stop under the basket.","fact":"After retiring he became a popular television host and analyst on basketball programmes.","wiki_en":"Shaquille O'Neal"},{"name":"Muhammad Ali","emoji":"🦋","meta":["boxer","United States","1942–2016"],"description":"The heavyweight boxer and three-time world champion, known not only for what he did in the ring but for his sharp talk and for the positions he took in public life outside it. Few athletes have ever been so famous for their words.","fact":"He described his style with the line \"float like a butterfly, sting like a bee\", one of the best-known phrases in sport.","wiki_en":"Muhammad Ali"},{"name":"Mike Tyson","emoji":"🥊","meta":["boxer","United States","1966"],"description":"The heavyweight boxer who became the youngest world heavyweight champion, known for an exceptionally powerful and fast style in the ring through the 1980s and 1990s, when opponents rarely lasted long against him.","fact":"He has since appeared in films and on television more than once, including playing himself in the comedy \"The Hangover\".","wiki_en":"Mike Tyson"},{"name":"Conor McGregor","emoji":"💥","meta":["MMA fighter","Ireland","1988"],"description":"The Irish mixed martial artist who became the first fighter in UFC history to hold championship belts in two weight classes at once. He is known for a loud, aggressive style both in the cage and in pre-fight interviews.","fact":"In 2017 he stepped into a boxing ring against Floyd Mayweather, in one of the best-selling fights in the history of boxing.","wiki_en":"Conor McGregor"},{"name":"Khabib Nurmagomedov","emoji":"🦅","meta":["MMA fighter","Russia","1988"],"description":"The Russian mixed martial artist and former UFC lightweight champion, who retired without a single defeat in his professional career. His wrestling-heavy style tended to leave opponents pinned to the mat.","fact":"His coach throughout his career was his father, Abdulmanap Nurmagomedov, a wrestling and sambo trainer.","wiki_en":"Khabib Nurmagomedov"},{"name":"Fedor Emelianenko","emoji":"🐻","meta":["MMA fighter","Russia","1976"],"description":"The Russian mixed martial artist who for years was regarded as one of the strongest heavyweights in the world, known above all for his title in the Pride organisation, where he built his reputation.","fact":"For many years he went unbeaten in professional fights, a rarity in the heavyweight division.","wiki_en":"Fedor Emelianenko"},{"name":"Roger Federer","emoji":"🎾","meta":["tennis player","Switzerland","1981"],"description":"The Swiss tennis player, a multiple Grand Slam champion who spent years at the top of the ATP rankings, known for the elegance of his game, which made even hard-won matches look easy.","fact":"He won Wimbledon eight times, more than any other player in the tournament's history.","wiki_en":"Roger Federer"},{"name":"Rafael Nadal","emoji":"🟧","meta":["tennis player","Spain","1986"],"description":"The Spanish tennis player who holds the record for wins at the clay-court tournament Roland Garros, known for extraordinary physical stamina and for a will to win every single point.","fact":"At Roland Garros he took the title more times than anyone in the history of tennis.","wiki_en":"Rafael Nadal"},{"name":"Novak Djokovic","emoji":"🧘","meta":["tennis player","Serbia","1987"],"description":"The Serbian tennis player who holds the record for weeks spent at number one in the ATP rankings, and one of the largest hauls of Grand Slam titles in the history of the sport. He has been a fixture at the top for well over a decade.","fact":"He has spent more weeks at the top of the ATP rankings than any other tennis player in history.","wiki_en":"Novak Djokovic"},{"name":"Serena Williams","emoji":"💪","meta":["tennis player","United States","1981"],"description":"The American tennis player, one of the strongest in the history of the women's game, with a long list of Grand Slam titles in both singles and doubles. Her serve was for years the most feared shot in the sport.","fact":"She and her elder sister Venus met each other in Grand Slam finals more than once.","wiki_en":"Serena Williams"},{"name":"Maria Sharapova","emoji":"🌟","meta":["tennis player","Russia","1987"],"description":"The Russian tennis player who won Wimbledon at seventeen, later reached number one in the world and went on to win all four Grand Slam tournaments over the course of her career, a feat only a handful of players have managed.","fact":"She won Wimbledon at seventeen, beating the defending champion, Serena Williams, in the final.","wiki_en":"Maria Sharapova"},{"name":"Tiger Woods","emoji":"⛳","meta":["golfer","United States","1975"],"description":"The American golfer, one of the most decorated players in the history of the game, who topped the world rankings for years and won the sport's biggest major tournaments again and again.","fact":"In 1997 he became the youngest winner of the Masters at Augusta, finishing with a record margin.","wiki_en":"Tiger Woods"},{"name":"Usain Bolt","emoji":"⚡","meta":["track and field athlete","Jamaica","1986"],"description":"The Jamaican sprinter, a multiple Olympic champion and world record holder over 100 and 200 metres, known as the fastest human being in history. His relaxed showmanship on the start line was almost as famous as his times.","fact":"His world records over 100 and 200 metres have now stood for more than a decade.","wiki_en":"Usain Bolt"},{"name":"Michael Phelps","emoji":"🏊","meta":["swimmer","United States","1985"],"description":"The American swimmer, the most decorated Olympian in history by number of gold medals, won across several consecutive Games. He specialised above all in butterfly and the individual medley.","fact":"At the 2008 Games in Beijing he won eight gold medals, more than anyone else at a single Olympics.","wiki_en":"Michael Phelps"},{"name":"Michael Schumacher","emoji":"🏎️","meta":["racing driver","Germany","1969"],"description":"The German Formula 1 driver, one of the most decorated champions in the history of the series, who spent many years with Ferrari. He is regarded as one of the drivers who shaped Formula 1 at the turn of the century.","fact":"He won the world championship several years in a row with Ferrari in the early 2000s.","wiki_en":"Michael Schumacher"},{"name":"Lewis Hamilton","emoji":"🏁","meta":["racing driver","United Kingdom","1985"],"description":"The British Formula 1 driver, one of the most decorated champions in the series, who spent many years with Mercedes and who is also known for taking an active public stance on social questions.","fact":"He shares the record for the number of Formula 1 world championship titles with Michael Schumacher.","wiki_en":"Lewis Hamilton"},{"name":"Alexander Ovechkin","emoji":"🏒","meta":["ice hockey player","Russia","1985"],"description":"The Russian ice hockey forward, for many years captain of the NHL club Washington Capitals, and the highest goal scorer in the history of the league. He is known for a huge shot and for almost two decades of consistent scoring.","fact":"In 2025 he passed Wayne Gretzky's record for goals scored in NHL regular seasons.","wiki_en":"Alexander Ovechkin"},{"name":"Wayne Gretzky","emoji":"🥅","meta":["ice hockey player","Canada","1961"],"description":"The Canadian ice hockey player often called the greatest in NHL history, holder of a whole stack of league scoring records and known by the nickname The Great One. He set goals up as readily as he scored them.","fact":"Many of his NHL scoring records have now stood unbeaten for several decades.","wiki_en":"Wayne Gretzky"},{"name":"Tom Brady","emoji":"🏈","meta":["American football player","United States","1977"],"description":"The American football quarterback, one of the most decorated players in NFL history, who spent most of his career with the New England Patriots and won the Super Bowl several times.","fact":"He has won the Super Bowl more times than any other player in the history of the NFL.","wiki_en":"Tom Brady"},{"name":"Tony Hawk","emoji":"🛹","meta":["skateboarding","United States","1968"],"description":"The American skateboarder, the best-known name in vertical skateboarding. At the X Games in 1999 he became the first person in history to land the \"900\", two and a half turns in the air. He also created a popular series of skateboarding video games.","fact":"The \"900\" did not come on the first attempt: at that legendary run in 1999 he fell several times before landing it cleanly.","wiki_en":"Tony Hawk"},{"name":"Simone Biles","emoji":"🤸","meta":["artistic gymnastics","United States","1997"],"description":"The American gymnast, one of the strongest in the history of artistic gymnastics. A multiple Olympic and world champion, she is known for elements of such difficulty that almost nobody before her dared attempt them in competition.","fact":"Several gymnastics elements are officially named after Simone Biles, as the first person to perform them at international events.","wiki_en":"Simone Biles"},{"name":"Garry Kasparov","emoji":"♟️","meta":["chess player","Russia","1963"],"description":"The Soviet and Russian chess player, world champion from 1985 to 2000. In 1997 he lost a famous match to the computer program Deep Blue. After his playing career he turned to public life and opposition politics.","fact":"Kasparov became the youngest world chess champion in history, taking the title at the age of twenty-two.","wiki_en":"Garry Kasparov"},{"name":"Magnus Carlsen","emoji":"👑","meta":["chess player","Norway","1990"],"description":"The Norwegian chess player, classical world champion from 2013 to 2023. He has held the top spot in the world Elo rankings for years and is considered one of the strongest players the game has ever seen.","fact":"Carlsen chose not to defend his world title in the following cycle, while remaining the leader of the world rankings.","wiki_en":"Magnus Carlsen"},{"name":"Lev Yashin","emoji":"🧤","meta":["goalkeeper","USSR","1929–1990"],"description":"The Soviet goalkeeper, for many years the man between the posts for Dynamo Moscow and the USSR national team. In 1963 he became the only goalkeeper in history to win the Ballon d'Or, the prize for the best footballer in Europe.","fact":"Yashin was nicknamed the Black Spider, for his all-black keeper's kit and his knack for reaching apparently hopeless shots.","wiki_en":"Lev Yashin"},{"name":"Evgeni Plushenko","emoji":"⛸️","meta":["figure skater","Russia","1982"],"description":"The Russian figure skater who competed in men's singles. An Olympic champion and a multiple world and European champion, he took part in four consecutive Olympic Games and came away with a medal from every one of them.","fact":"Plushenko took Olympic gold at the 2006 Games in Turin, having already won silver at the 2002 Olympics.","wiki_en":"Evgeni Plushenko"},{"name":"Alina Zagitova","emoji":"🥇","meta":["figure skater","Russia","2002"],"description":"The Russian figure skater, Olympic champion in women's singles in 2018 and European champion in the same season. She was only fifteen years old at the time of her triumph in Pyeongchang.","fact":"At the 2018 Olympics Zagitova finished ahead of her compatriot Evgenia Medvedeva by roughly a single point across the two programmes.","wiki_en":"Alina Zagitova"},{"name":"Yuri Gagarin","emoji":"🚀","meta":["cosmonaut","USSR","1934–1968"],"description":"The Soviet pilot and cosmonaut, the first human being to fly in space. On 12 April 1961, aboard the spacecraft Vostok 1, he circled the Earth in orbit in 108 minutes. He died in 1968 in a plane crash during a training flight.","fact":"In honour of Gagarin's flight, 12 April is marked as the International Day of Human Space Flight.","wiki_en":"Yuri Gagarin"},{"name":"Yuri Nikulin","emoji":"🤡","meta":["actor and clown","USSR","1921–1997"],"description":"The Soviet actor and circus performer, for many years director of the Moscow Circus on Tsvetnoy Boulevard. He appeared in Leonid Gaidai's comedies and in the war drama \"They Fought for Their Country\", combining a film career with work as a clown in the ring.","fact":"Nikulin fought through the Second World War and spent about seven years in the army altogether.","wiki_en":"Yuri Nikulin"},{"name":"Andrei Mironov","emoji":"🎭","meta":["actor","USSR","1941–1987"],"description":"The Soviet stage and screen actor, a leading player at the Moscow Satire Theatre. He appeared in the comedies of Leonid Gaidai and Eldar Ryazanov, among them \"The Diamond Arm\" and \"Unbelievable Adventures of Italians in Russia\".","fact":"Mironov collapsed on stage during a touring performance in Riga and died two days later.","wiki_en":"Andrei Mironov"},{"name":"Sergei Bodrov Jr.","emoji":"🎬","meta":["actor and director","Russia","1971–2002"],"description":"The Russian actor, director and television presenter who became famous as Danila Bagrov in the films \"Brother\" and \"Brother 2\". He died in 2002 in the Karmadon Gorge, when the Kolka glacier collapsed while he was shooting a new film.","fact":"Sergei Bodrov's body was never found after the collapse of the Kolka glacier in North Ossetia.","wiki_en":"Sergei Bodrov Jr."},{"name":"Danila Kozlovsky","emoji":"🎥","meta":["actor and director","Russia","1985"],"description":"The Russian stage and screen actor and director. He became widely known after the film \"We Are from the Future\" and his role in \"Soulless\", and has also worked on foreign productions, among them \"Vampire Academy\".","fact":"Kozlovsky made his feature directing debut with \"Coach\", in which he also played the lead.","wiki_en":"Danila Kozlovsky"},{"name":"Konstantin Khabensky","emoji":"🎟️","meta":["actor","Russia","1972"],"description":"The Russian stage and screen actor, for many years a member of the Chekhov Moscow Art Theatre, which he also ran as artistic director for several years in the 2020s. He is widely known for \"Night Watch\", \"Day Watch\" and \"Admiral\".","fact":"Khabensky founded a charity that helps children with cancer and other serious illnesses of the brain.","wiki_en":"Konstantin Khabensky"},{"name":"Sergei Bezrukov","emoji":"🖋️","meta":["actor","Russia","1973"],"description":"The Russian stage and screen actor, artistic director of the Moscow Provincial Theatre. He became widely known as Sasha Bely in the series \"Brigada\" and as the poet Sergei Yesenin in the television film of the same name.","fact":"In the 2005 television version of \"The Master and Margarita\" he played Yeshua Ha-Nozri and also voiced the cat Behemoth.","wiki_en":"Sergei Bezrukov"},{"name":"Ivan Urgant","emoji":"🎙️","meta":["television host","Russia","1978"],"description":"The Russian television host, showman and actor who for many years fronted the nightly programme \"Evening Urgant\" on Channel One. He has also voiced animated characters and hosted a range of television awards ceremonies.","fact":"\"Evening Urgant\" was on the air almost every weekday for around ten years in a row.","wiki_en":"Ivan Urgant"},{"name":"Yury Dud","emoji":"🎧","meta":["journalist","Russia","1986"],"description":"The Russian journalist behind the interview show \"vDud\" on YouTube. He worked earlier as a sports journalist and as editor-in-chief of the Sports.ru portal, before switching to long video interviews with well-known people.","fact":"Individual episodes of \"vDud\" on YouTube drew tens of millions of views.","wiki_en":"Yury Dud"},{"name":"Irina Shayk","emoji":"📸","meta":["model","Russia","1986"],"description":"The Russian supermodel who has appeared on the covers of Vogue, GQ and other glossy magazines and was for years the face of the Italian lingerie brand Intimissimi. She has walked for the leading fashion houses and taken part in the Victoria's Secret show.","fact":"Irina Shayk comes from the Chelyabinsk region and began her modelling career in local beauty contests.","wiki_en":"Irina Shayk"},{"name":"Natalia Vodianova","emoji":"🎗️","meta":["model","Russia","1982"],"description":"The Russian supermodel and founder of the Naked Heart Foundation, a charity for children with developmental disabilities. She started out in modelling after selling fruit at a market in her native Nizhny Novgorod.","fact":"The Naked Heart Foundation, set up by Vodianova, builds inclusive playgrounds in cities across Russia.","wiki_en":"Natalia Vodianova"},{"name":"Donald Trump","emoji":"🎩","meta":["President of the United States","United States","1946"],"description":"The American businessman and politician, 45th president of the United States from 2017 to 2021 and 47th president since 2025. Before he entered politics he worked in real estate and hosted the reality show \"The Apprentice\".","fact":"Trump became the first US president in more than a hundred years to be elected to two non-consecutive terms.","wiki_en":"Donald Trump"},{"name":"Joe Biden","emoji":"🕶️","meta":["President of the United States","United States","1942"],"description":"The American politician, 46th president of the United States from 2021 to 2025. Before that he represented the state of Delaware in the US Senate for a long time and was vice-president under Barack Obama from 2009 to 2017.","fact":"Biden took office as president of the United States at an older age than any of his predecessors.","wiki_en":"Joe Biden"},{"name":"Barack Obama","emoji":"🎓","meta":["President of the United States","United States","1961"],"description":"The American politician, 44th president of the United States from 2009 to 2017 and the first African American to hold the office. Before his election he served as a senator from Illinois and taught constitutional law at the University of Chicago.","fact":"In 2009, shortly after taking office, Obama was awarded the Nobel Peace Prize.","wiki_en":"Barack Obama"},{"name":"George W. Bush","emoji":"🤠","meta":["President of the United States","United States","1946"],"description":"The American politician, 43rd president of the United States from 2001 to 2009 and son of the 41st president, George H. W. Bush. His presidency took in the attacks of 11 September 2001 and the military operations in Afghanistan and Iraq that followed.","fact":"Bush and his father were the second father-and-son pair in US history to hold the presidency, after John Adams and John Quincy Adams.","wiki_en":"George W. Bush"},{"name":"Bill Clinton","emoji":"🎷","meta":["President of the United States","United States","1946"],"description":"The American politician, 42nd president of the United States from 1993 to 2001, who had earlier been governor of Arkansas. During his second term he faced impeachment proceedings brought by the House of Representatives.","fact":"Bill Clinton plays the saxophone and has performed on it in public more than once, including on television shows.","wiki_en":"Bill Clinton"},{"name":"Ronald Reagan","emoji":"🎬","meta":["President of the United States","United States","1911–2004"],"description":"The American politician and actor, 40th president of the United States from 1981 to 1989. Before moving into politics he appeared in films, and then served two terms as governor of California.","fact":"Before he became governor and then president, Reagan had appeared in more than fifty films.","wiki_en":"Ronald Reagan"},{"name":"John F. Kennedy","emoji":"⭐","meta":["President of the United States","United States","1917–1963"],"description":"The American politician, 35th president of the United States, in office from 1961 until his death in 1963. His presidency fell at the height of the Cold War, and took in the Cuban missile crisis of 1962.","fact":"Kennedy was shot in Dallas on 22 November 1963, as the presidential motorcade drove through the city.","wiki_en":"John F. Kennedy"},{"name":"Richard Nixon","emoji":"🖊️","meta":["President of the United States","United States","1913–1994"],"description":"The American politician, 37th president of the United States from 1969 to 1974. He remains the only US president to have left the post early, resigning in 1974 against the background of the Watergate scandal.","fact":"Nixon announced his resignation in a televised address to the nation on 8 August 1974.","wiki_en":"Richard Nixon"},{"name":"Franklin D. Roosevelt","emoji":"🏛️","meta":["President of the United States","United States","1882–1945"],"description":"The American politician, 32nd president of the United States, in office from 1933 until his death in 1945, and the only president ever elected to the office four times. He led the country through the Great Depression and most of the Second World War.","fact":"After Roosevelt's death the 22nd Amendment to the US Constitution was adopted, limiting the presidency to two terms.","wiki_en":"Franklin D. Roosevelt"},{"name":"Abraham Lincoln","emoji":"🪓","meta":["President of the United States","United States","1809–1865"],"description":"The American politician, 16th president of the United States, in office from 1861 until his assassination in 1865. He led the country through the Civil War and signed the Emancipation Proclamation in 1863.","fact":"Lincoln was shot at Ford's Theatre in Washington a few days after the end of the Civil War.","wiki_en":"Abraham Lincoln"},{"name":"George Washington","emoji":"🌳","meta":["President of the United States","United States","1732–1799"],"description":"The American statesman and soldier, first president of the United States, in office from 1789 to 1797. He commanded the colonial army in the War of Independence from Britain and stepped down voluntarily after two terms.","fact":"Legend has it that the young Washington cut down his father's cherry tree and honestly owned up to it, though historians take the story to be an invention.","wiki_en":"George Washington"},{"name":"Thomas Jefferson","emoji":"📜","meta":["President of the United States","United States","1743–1826"],"description":"The American statesman, third president of the United States from 1801 to 1809, and one of the authors of the Declaration of Independence of 1776. Under him the country's territory nearly doubled, thanks to the Louisiana Purchase from France.","fact":"Jefferson died on 4 July 1826, the fiftieth anniversary of the adoption of the Declaration of Independence.","wiki_en":"Thomas Jefferson"},{"name":"Theodore Roosevelt","emoji":"🐻","meta":["President of the United States","United States","1858–1919"],"description":"The American politician, 26th president of the United States from 1901 to 1909 and one of the youngest men ever to hold the office. He is known for his conservation policy: many of the national parks and reserves of the United States were created under him.","fact":"The teddy bear was named after Theodore Roosevelt, after an incident in which he refused to shoot a bear tied up for him on a hunt.","wiki_en":"Theodore Roosevelt"},{"name":"Hillary Clinton","emoji":"💼","meta":["politician","United States","1947"],"description":"The American politician and diplomat, US secretary of state from 2009 to 2013 under President Barack Obama. Earlier she was a senator from the state of New York and first lady of the United States during her husband Bill Clinton's presidency.","fact":"In 2016 Hillary Clinton became the first woman nominated for president of the United States by one of the country's two main parties.","wiki_en":"Hillary Clinton"},{"name":"Kamala Harris","emoji":"⚖️","meta":["Vice President of the United States","United States","1964"],"description":"The American politician, vice-president of the United States from 2021 to 2025 under Joe Biden, and the first woman in the post. Before that she held the offices of attorney general of California and senator from that state.","fact":"In 2024 Harris became the Democratic Party's candidate in the presidential election, after Joe Biden withdrew from the race.","wiki_en":"Kamala Harris"},{"name":"Bernie Sanders","emoji":"🏔️","meta":["senator","United States","1941"],"description":"The American politician, an independent senator from the state of Vermont. He twice ran in the Democratic Party primaries for the US presidential nomination, in 2016 and in 2020, but did not win it.","fact":"Sanders is the longest-serving independent member of the US Congress in the country's history.","wiki_en":"Bernie Sanders"},{"name":"JD Vance","emoji":"📖","meta":["Vice President of the United States","United States","1984"],"description":"The American politician and writer, vice-president of the United States since 2025 under Donald Trump. Before politics he published the memoir \"Hillbilly Elegy\", about life in a working-class Appalachian family, and then served briefly as a senator from Ohio.","fact":"Before becoming a senator, JD Vance served in the US Marine Corps and went to the Iraq war as a military journalist.","wiki_en":"JD Vance"},{"name":"Henry Kissinger","emoji":"🤝","meta":["US Secretary of State","United States","1923–2023"],"description":"The American diplomat and political scientist, US secretary of state from 1973 to 1977 under Presidents Nixon and Ford. He played a key part in normalising relations between the United States and China and in the talks to end the war in Vietnam.","fact":"In 1973 Kissinger was awarded the Nobel Peace Prize for the Vietnam ceasefire talks, a decision that caused arguments among members of the Nobel committee.","wiki_en":"Henry Kissinger"},{"name":"Martin Luther King Jr.","emoji":"🕊️","meta":["activist","United States","1929–1968"],"description":"The American Baptist preacher and one of the leaders of the movement for African American civil rights. In 1963 he delivered the speech \"I Have a Dream\" during the March on Washington. He was shot dead in Memphis in 1968.","fact":"In 1964 Martin Luther King became the youngest person up to that point to receive the Nobel Peace Prize.","wiki_en":"Martin Luther King Jr."},{"name":"Vladimir Putin","emoji":"🏛️","meta":["President of Russia","Russia","1952"],"description":"The Russian statesman, president of Russia since 2000, with a break from 2008 to 2012 when he held the post of prime minister. Before going into politics he worked in the state security services, including a posting in Germany.","fact":"Putin has held the posts of president and prime minister of Russia for longer, in total, than any other leader of the country since Joseph Stalin.","wiki_en":"Vladimir Putin"},{"name":"Dmitry Medvedev","emoji":"💻","meta":["former President of Russia","Russia","1965"],"description":"The Russian statesman, president of Russia from 2008 to 2012 and then prime minister from 2012 to 2020. A lawyer by training, before his election as president he worked in the presidential administration and on the board of Gazprom.","fact":"As president, Medvedev launched a reform of the law enforcement agencies under which the militia was renamed the police.","wiki_en":"Dmitry Medvedev"},{"name":"Boris Yeltsin","emoji":"📜","meta":["former President of Russia","Russia","1931–2007"],"description":"The Russian statesman, the first president of Russia, in office from 1991 to 1999. He led the country through the break-up of the USSR and the market reforms of the 1990s, and announced his resignation on the last day of 1999.","fact":"In his New Year address on 31 December 1999, Yeltsin announced his early resignation, handing power to the prime minister, Vladimir Putin.","wiki_en":"Boris Yeltsin"},{"name":"Mikhail Gorbachev","emoji":"🌍","meta":["General Secretary of the CPSU Central Committee","USSR","1931–2022"],"description":"The Soviet statesman and the last leader of the USSR: General Secretary of the CPSU Central Committee from 1985 to 1991 and the first president of the Soviet Union. He launched perestroika and glasnost, which brought sweeping change to the country and the world.","fact":"In 1990 Gorbachev was awarded the Nobel Peace Prize for his contribution to ending the Cold War.","wiki_en":"Mikhail Gorbachev"},{"name":"Leonid Brezhnev","emoji":"🎖️","meta":["General Secretary of the CPSU Central Committee","USSR","1906–1982"],"description":"The Soviet statesman, General Secretary of the CPSU Central Committee from 1964 to 1982. His long rule was a period of relative stability in the USSR, which later came to be known as the Era of Stagnation.","fact":"Brezhnev was awarded a great many orders and medals, including four Hero of the Soviet Union stars.","wiki_en":"Leonid Brezhnev"},{"name":"Nikita Khrushchev","emoji":"🌽","meta":["First Secretary of the CPSU Central Committee","USSR","1894–1971"],"description":"The Soviet statesman, First Secretary of the CPSU Central Committee from 1953 to 1964. In 1956 he delivered a report on Stalin's cult of personality, and in 1962 he became one of the central figures of the Cuban missile crisis.","fact":"In 1964 Khrushchev was removed from power by a plenum of the CPSU Central Committee, and lived out his life in retirement.","wiki_en":"Nikita Khrushchev"},{"name":"Joseph Stalin","emoji":"🪖","meta":["General Secretary of the All-Union Communist Party Central Committee","USSR","1878–1953"],"description":"The Soviet statesman who led the USSR from the end of the 1920s until his death in 1953. Under him the country went through industrialisation, collectivisation, mass repressions and victory in the Second World War.","fact":"Stalin's real surname was Dzhugashvili; \"Stalin\" was a party alias that had stuck to him even before the revolution.","wiki_en":"Joseph Stalin"},{"name":"Vladimir Lenin","emoji":"🚩","meta":["Chairman of the Council of People's Commissars","USSR","1870–1924"],"description":"The Russian revolutionary and statesman, leader of the Bolsheviks and organiser of the October Revolution of 1917. Founder of the Soviet state, he headed the government of the RSFSR and then of the USSR until his death in 1924.","fact":"After his death Lenin's body was embalmed and placed in the Mausoleum on Red Square in Moscow, where it lies to this day.","wiki_en":"Vladimir Lenin"},{"name":"Nicholas II","emoji":"👑","meta":["Emperor of Russia","Russia","1868–1918"],"description":"The last Russian emperor, who reigned from 1894 to 1917. He abdicated the throne during the February Revolution of 1917, and was shot together with his family in Yekaterinburg in 1918.","fact":"In 2000 Nicholas II and members of his family were canonised by the Russian Orthodox Church as passion bearers.","wiki_en":"Nicholas II of Russia"},{"name":"Peter the Great","emoji":"⚓","meta":["Tsar and Emperor of Russia","Russia","1672–1725"],"description":"Tsar of Russia and, from 1721, the first Russian emperor. He carried out sweeping reforms of the army, the navy, government and everyday life, and founded Saint Petersburg, which became the new capital.","fact":"Peter I learned crafts himself, shipbuilding among them, working incognito in Dutch shipyards during the Grand Embassy.","wiki_en":"Peter the Great"},{"name":"Catherine the Great","emoji":"👑","meta":["Empress of Russia","Russia","1729–1796"],"description":"The Russian empress, who reigned from 1762 to 1796. Under her the territory of the empire expanded considerably, including the annexation of Crimea, and Russia strengthened its position as one of the leading European powers.","fact":"Catherine II came to the throne through a palace coup, overthrowing her husband, Emperor Peter III.","wiki_en":"Catherine the Great"},{"name":"Sergey Lavrov","emoji":"🤵","meta":["Foreign Minister of Russia","Russia","1950"],"description":"The Russian diplomat, foreign minister of Russia since 2004. Before his appointment to the ministry he spent many years representing Russia at the United Nations as its permanent representative.","fact":"Lavrov has held the post of Russian foreign minister for longer than any of his predecessors in the country's recent history.","wiki_en":"Sergey Lavrov"},{"name":"Xi Jinping","emoji":"🐉","meta":["President of the PRC","China","1953"],"description":"The Chinese statesman, president of the People's Republic of China since 2013 and General Secretary of the Communist Party of China since 2012. As a young man he spent several years in the countryside during the Cultural Revolution.","fact":"In 2018 an amendment to the constitution of the PRC removed the limit on the number of consecutive presidential terms.","wiki_en":"Xi Jinping"},{"name":"Mao Zedong","emoji":"📕","meta":["Chairman of the PRC","China","1893–1976"],"description":"The Chinese revolutionary and statesman, founder of the People's Republic of China, which was proclaimed in 1949. He led the country and the ruling Communist Party of China from then until his death in 1976.","fact":"Mao Zedong's body was embalmed and is on display in a mausoleum on Tiananmen Square in Beijing.","wiki_en":"Mao Zedong"},{"name":"Deng Xiaoping","emoji":"🏗️","meta":["leader of China","China","1904–1997"],"description":"The Chinese statesman, the effective leader of China from the end of the 1970s and the initiator of the policy of reform and opening up. Under him China began its shift to a market economy while keeping the one-party political system.","fact":"Deng Xiaoping never formally held the post of head of state or of the party, running the country from less conspicuous offices.","wiki_en":"Deng Xiaoping"},{"name":"Narendra Modi","emoji":"🪷","meta":["Prime Minister of India","India","1950"],"description":"The Indian statesman, prime minister of India since 2014 and leader of the Bharatiya Janata Party. Before that he spent many years in the post of chief minister of the state of Gujarat.","fact":"Modi is the first prime minister of India to have been born after the country's independence was declared in 1947.","wiki_en":"Narendra Modi"},{"name":"Mahatma Gandhi","emoji":"🕊️","meta":["leader of the Indian independence movement","India","1869–1948"],"description":"The Indian public and political figure who led India's movement for liberation from British colonial rule. He worked out a strategy of non-violent civil resistance that shaped rights movements all over the world.","fact":"Gandhi was shot dead in Delhi in 1948, a few months after India gained its independence.","wiki_en":"Mahatma Gandhi"},{"name":"Indira Gandhi","emoji":"🌺","meta":["Prime Minister of India","India","1917–1984"],"description":"The Indian politician, prime minister of India from 1966 to 1977 and again from 1980 to 1984, and daughter of the country's first prime minister, Jawaharlal Nehru. She was killed by her own bodyguards in 1984.","fact":"Indira Gandhi was not related to Mahatma Gandhi; the shared surname came from her husband.","wiki_en":"Indira Gandhi"},{"name":"Shinzo Abe","emoji":"🎯","meta":["Prime Minister of Japan","Japan","1954–2022"],"description":"The Japanese statesman, prime minister of Japan from 2006 to 2007 and again from 2012 to 2020, longer than anyone else in the country's history in that post. He was shot during an election campaign speech in 2022.","fact":"Abe was killed with a homemade firearm during a public speech in the city of Nara in July 2022.","wiki_en":"Shinzo Abe"},{"name":"Kim Jong Un","emoji":"🚂","meta":["leader of North Korea","North Korea","1984"],"description":"The North Korean statesman, leader of the DPRK since the end of 2011, after the death of his father Kim Jong Il. He represents the third generation of the Kim dynasty that rules the country.","fact":"Kim Jong Un was partly educated in Switzerland, attending a school near Bern under an assumed name.","wiki_en":"Kim Jong Un"},{"name":"Lee Kuan Yew","emoji":"🌆","meta":["Prime Minister of Singapore","Singapore","1923–2015"],"description":"The Singaporean statesman, the first prime minister of independent Singapore, in the post from 1959 to 1990. He is regarded as the founder of the modern Singaporean state: under him the country went from a poor colony to one of the financial centres of Asia.","fact":"After leaving the premiership in 1990, Lee Kuan Yew spent many more years as senior minister in the Singapore government.","wiki_en":"Lee Kuan Yew"},{"name":"Emmanuel Macron","emoji":"🐓","meta":["President of France","France","1977"],"description":"The French statesman, president of France since 2017. Before his election he worked as an investment banker and as economy minister, and he became the youngest president of France in the entire history of the Fifth Republic.","fact":"Before the presidency Macron founded his own political movement, En Marche!, and won the election with it, without a large party behind him.","wiki_en":"Emmanuel Macron"},{"name":"Charles de Gaulle","emoji":"✈️","meta":["President of France","France","1890–1970"],"description":"The French general and statesman, leader of Free France during the Second World War, then founder of the Fifth Republic and its first president, in office from 1959 to 1969 under a constitution built around a strong presidency.","fact":"De Gaulle resigned as president in 1969, after losing a national referendum on the reform of the Senate and the regions.","wiki_en":"Charles de Gaulle"},{"name":"Napoleon Bonaparte","emoji":"⚔️","meta":["Emperor of France","France","1769–1821"],"description":"The French general and statesman, emperor of France from 1804 to 1814 and again in 1815. He fought a series of campaigns across the whole of Europe and, after his defeat at Waterloo, was exiled to the island of Saint Helena, where he died.","fact":"After his first abdication Napoleon was exiled to Elba, but within a year he escaped and took back power in France for a hundred days.","wiki_en":"Napoleon"},{"name":"Angela Merkel","emoji":"🔬","meta":["Federal Chancellor of Germany","Germany","1954"],"description":"The German politician, federal chancellor of Germany from 2005 to 2021 and the first woman in the post. A physicist by training, she worked in research in East Germany before the reunification.","fact":"Merkel led the German government for sixteen years, almost as long as Helmut Kohl before her.","wiki_en":"Angela Merkel"},{"name":"Olaf Scholz","emoji":"🚦","meta":["former Chancellor of Germany","Germany","1958"],"description":"The German politician, federal chancellor of Germany from 2021 to 2025 and a member of the Social Democratic Party. Before that he held the posts of finance minister and vice-chancellor, as well as first mayor of Hamburg.","fact":"Scholz's government, which brought together three parties with different views, was nicknamed the \"traffic light coalition\" in the German press, after the parties' colours.","wiki_en":"Olaf Scholz"},{"name":"Friedrich Merz","emoji":"💼","meta":["Federal Chancellor of Germany","Germany","1955"],"description":"The German politician, federal chancellor of Germany since 2025 and chairman of the Christian Democratic Union. Earlier he worked for a long time as a lawyer and in business, before returning to front-line politics.","fact":"Merz took office as chancellor only at the second round of voting in the Bundestag, a rare event in the history of postwar Germany.","wiki_en":"Friedrich Merz"},{"name":"Otto von Bismarck","emoji":"⚙️","meta":["Chancellor of the German Empire","Germany","1815–1898"],"description":"The Prussian and German statesman, the first chancellor of the united German Empire, in the post from 1871 to 1890. He played a key part in uniting the German lands around Prussia.","fact":"Bismarck is called the Iron Chancellor, a nickname tied to his line that the great questions of the age are settled by iron and blood.","wiki_en":"Otto von Bismarck"},{"name":"Winston Churchill","emoji":"✌️","meta":["Prime Minister of the United Kingdom","United Kingdom","1874–1965"],"description":"The British statesman, prime minister of the United Kingdom from 1940 to 1945 and again from 1951 to 1955. He led the country through the hardest stretch of the Second World War, and is also known as a writer and a Nobel laureate in literature.","fact":"In 1953 Churchill received the Nobel Prize in Literature, for his historical and biographical writing and for his oratory.","wiki_en":"Winston Churchill"},{"name":"Margaret Thatcher","emoji":"👛","meta":["Prime Minister of the United Kingdom","United Kingdom","1925–2013"],"description":"The British politician, prime minister of the United Kingdom from 1979 to 1990 and the first woman in the post. A chemist by training, she worked as a research scientist and then as a lawyer before her political career.","fact":"Thatcher earned the nickname the Iron Lady after a speech in the mid-1970s in which she sharply criticised Soviet policy.","wiki_en":"Margaret Thatcher"},{"name":"Tony Blair","emoji":"💼","meta":["Prime Minister of the United Kingdom","United Kingdom","1953"],"description":"The British statesman, prime minister of the United Kingdom from 1997 to 2007 and leader of the Labour Party. He was one of the youngest British prime ministers of the twentieth century at the moment he took office.","fact":"Blair led the British government for three consecutive terms, more than any other Labour leader in the party's history.","wiki_en":"Tony Blair"},{"name":"Boris Johnson","emoji":"🚲","meta":["Prime Minister of the United Kingdom","United Kingdom","1964"],"description":"The British politician and journalist, prime minister of the United Kingdom from 2019 to 2022. Before that he held the posts of mayor of London and foreign secretary, and he was one of the central figures in the campaign for Britain to leave the EU.","fact":"Before he moved into front-line politics Johnson worked as a journalist, and was widely known for his trademark dishevelled hair.","wiki_en":"Boris Johnson"},{"name":"Keir Starmer","emoji":"⚖️","meta":["Prime Minister of the United Kingdom","United Kingdom","1962"],"description":"The British politician and lawyer, prime minister of the United Kingdom since 2024 and leader of the Labour Party. Before politics he worked as a Queen's Counsel and as Director of Public Prosecutions for England and Wales.","fact":"Starmer was knighted for services to law before he was ever elected to parliament, so he officially holds the title Sir.","wiki_en":"Keir Starmer"},{"name":"Elizabeth II","emoji":"👑","meta":["Queen of the United Kingdom","United Kingdom","1926–2022"],"description":"Queen of the United Kingdom and of a number of other Commonwealth realms, on the throne from 1952 to 2022, longer than any other British monarch in history. She came to the throne at twenty-five, after the death of her father, King George VI.","fact":"About fifteen prime ministers came and went in Britain during her reign, from Winston Churchill to Liz Truss.","wiki_en":"Elizabeth II"},{"name":"Charles III","emoji":"👑","meta":["King of the United Kingdom","United Kingdom","1948"],"description":"King of the United Kingdom and of a number of other Commonwealth realms since 2022, and the eldest son of Queen Elizabeth II. Before he came to the throne he held the title Prince of Wales for longer than any heir to the British crown in history.","fact":"Charles III was the oldest monarch at the moment of coronation in the whole history of the British crown.","wiki_en":"Charles III"},{"name":"Queen Victoria","emoji":"👑","meta":["Queen of the United Kingdom","United Kingdom","1819–1901"],"description":"Queen of the United Kingdom, who reigned from 1837 to 1901, one of the longest reigns in the country's history and the one that gave the Victorian era its name. Under her the British Empire reached its greatest territorial extent.","fact":"Through her many children and grandchildren Victoria was called the grandmother of Europe: her descendants ruled in many European monarchies.","wiki_en":"Queen Victoria"},{"name":"Giorgia Meloni","emoji":"🎤","meta":["Prime Minister of Italy","Italy","1977"],"description":"The Italian politician, president of the Council of Ministers of Italy since 2022 and the first woman in the post. She leads the Brothers of Italy party, with which she came to power after parliamentary elections.","fact":"She co-founded Brothers of Italy in 2012, and in ten years it grew into one of the leading forces in the Italian parliament.","wiki_en":"Giorgia Meloni"},{"name":"Silvio Berlusconi","emoji":"⚽","meta":["Prime Minister of Italy","Italy","1936–2023"],"description":"The Italian businessman and politician, three times president of the Council of Ministers of Italy between 1994 and 2011. He owned large media assets, television channels among them, as well as the football club Milan.","fact":"Berlusconi was president of the football club Milan during a period when the team won the UEFA Champions League several times.","wiki_en":"Silvio Berlusconi"},{"name":"Recep Tayyip Erdoğan","emoji":"🕌","meta":["President of Turkey","Turkey","1954"],"description":"The Turkish statesman, president of Turkey since 2014 and before that prime minister of the country from 2003. He began his political career as mayor of Istanbul in the 1990s, and has shaped Turkish politics ever since.","fact":"Under Erdoğan, Turkey moved from a parliamentary to a presidential system of government, following the constitutional referendum of 2017.","wiki_en":"Recep Tayyip Erdoğan"},{"name":"Mustafa Kemal Atatürk","emoji":"🏛️","meta":["founder of the Republic of Turkey","Turkey","1881–1938"],"description":"The Turkish general and statesman, founder and first president of the Republic of Turkey, which was proclaimed in 1923. He carried out sweeping secular reforms that changed the country's political system, its alphabet and its way of life.","fact":"The surname Atatürk, meaning \"father of the Turks\", was conferred on him by a special law of the Turkish parliament in 1934.","wiki_en":"Mustafa Kemal Atatürk"},{"name":"Benjamin Netanyahu","emoji":"📢","meta":["Prime Minister of Israel","Israel","1949"],"description":"The Israeli statesman, prime minister of Israel for longer than anyone else in the country's history: he held the post from 1996 to 1999 and again from 2009, with a break. He leads the Likud party.","fact":"Netanyahu was the first prime minister of Israel to be born after the state declared its independence in 1948.","wiki_en":"Benjamin Netanyahu"},{"name":"Mohammed bin Salman","emoji":"🛢️","meta":["Crown Prince of Saudi Arabia","Saudi Arabia","1985"],"description":"The Saudi statesman, crown prince and prime minister of Saudi Arabia, who has effectively run the country since the middle of the 2010s. He launched the Vision 2030 programme of economic reform, aimed at reducing the country's dependence on oil.","fact":"On Mohammed bin Salman's initiative, women in Saudi Arabia were officially allowed to drive a car in 2018.","wiki_en":"Mohammed bin Salman"},{"name":"Volodymyr Zelenskyy","emoji":"🎭","meta":["President of Ukraine","Ukraine","1978"],"description":"The Ukrainian statesman, president of Ukraine since 2019. Before entering politics he was an actor and comedian: he starred in the television series \"Servant of the People\", playing the country's president, and then led the party of the same name.","fact":"Before becoming president, Zelenskyy voiced Paddington Bear in the Ukrainian dub of the \"Paddington\" films.","wiki_en":"Volodymyr Zelenskyy"},{"name":"Alexander Lukashenko","emoji":"🐄","meta":["President of Belarus","Belarus","1954"],"description":"The Belarusian statesman, president of Belarus since 1994, the first and so far the only person to hold the post. Before his election as president he ran a state farm in the Mogilev region.","fact":"Lukashenko became president of Belarus at the country's first ever presidential election, winning in 1994.","wiki_en":"Alexander Lukashenko"},{"name":"Viktor Orbán","emoji":"🏰","meta":["Prime Minister of Hungary","Hungary","1963"],"description":"The Hungarian statesman, prime minister of Hungary since 2010, who had already held the post from 1998 to 2002. Leader of the Fidesz party, in his youth he took part in the dissident movement of socialist Hungary's final years.","fact":"In 1989 Orbán gave a public speech in Budapest calling for Soviet troops to be withdrawn from Hungary.","wiki_en":"Viktor Orbán"},{"name":"Ursula von der Leyen","emoji":"🏢","meta":["President of the European Commission","Germany","1958"],"description":"The German politician, president of the European Commission since 2019 and the first woman in the post. Before she moved up to the European level she served as Germany's minister of defence in Angela Merkel's government.","fact":"Von der Leyen partly grew up in Brussels, where her father worked in the bodies that later became the European Commission.","wiki_en":"Ursula von der Leyen"},{"name":"António Guterres","emoji":"🌐","meta":["UN Secretary-General","Portugal","1949"],"description":"The Portuguese statesman and diplomat, secretary-general of the United Nations since 2017. Before that he was prime minister of Portugal, and then spent many years in senior positions within the UN system.","fact":"Before his election as UN secretary-general, Guterres spent about ten years as UN High Commissioner for Refugees.","wiki_en":"António Guterres"},{"name":"John Paul II","emoji":"✝️","meta":["Pope","Poland","1920–2005"],"description":"Pope from 1978 to 2005, the first pope of Polish origin and the first non-Italian in the office for more than four hundred years. One of the longest-reigning popes in the history of the Catholic Church, he was canonised in 2014.","fact":"In 1981 an attempt was made on John Paul II's life in St Peter's Square; he was badly wounded but survived.","wiki_en":"Pope John Paul II"},{"name":"Leo XIV","emoji":"✝️","meta":["Pope","United States","1955"],"description":"Pope since 2025, born Robert Francis Prevost, the first pope born in the United States. Before his election he spent many years as a missionary in Peru and headed the Vatican body responsible for bishops.","fact":"He belongs to the Augustinian order and, during his years of work in Peru, also took Peruvian citizenship.","wiki_en":"Pope Leo XIV"},{"name":"The 14th Dalai Lama","emoji":"🙏","meta":["spiritual leader of Tibetan Buddhism","Tibet","1935"],"description":"The spiritual leader of Tibetan Buddhism, recognised as the fourteenth Dalai Lama in early childhood. He has lived in exile in India since 1959, after the suppression of the uprising in Tibet, and remains a symbol of Tibetan culture and religion.","fact":"In 1989 the 14th Dalai Lama was awarded the Nobel Peace Prize for his non-violent struggle for the rights of the Tibetan people.","wiki_en":"14th Dalai Lama"},{"name":"Nelson Mandela","emoji":"⛓️","meta":["President of South Africa","South Africa","1918–2013"],"description":"The South African statesman and campaigner, the first president of South Africa to be elected at a national vote with universal suffrage, in office from 1994 to 1999. He spent 27 years in prison for his struggle against apartheid.","fact":"In 1993, before he was elected president, Mandela received the Nobel Peace Prize together with President Frederik de Klerk.","wiki_en":"Nelson Mandela"},{"name":"Fidel Castro","emoji":"🚬","meta":["Chairman of the Council of State of Cuba","Cuba","1926–2016"],"description":"The Cuban revolutionary and statesman, leader of Cuba for almost half a century, from the victory of the revolution in 1959 until he handed power to his brother Raúl in 2008. He nationalised the economy on a huge scale and built a one-party socialist system in Cuba.","fact":"Over the years of his rule in Cuba, about ten US presidents came and went in the White House.","wiki_en":"Fidel Castro"},{"name":"Che Guevara","emoji":"📷","meta":["revolutionary","Argentina","1928–1967"],"description":"The Argentine revolutionary, one of the leaders of the Cuban Revolution of 1959 and a comrade of Fidel Castro. A doctor by training, he later tried to spark revolutionary movements in Congo and Bolivia, where he was captured and executed in 1967.","fact":"The portrait of Che Guevara in a beret, taken by the photographer Alberto Korda, became one of the most reproduced images of the twentieth century.","wiki_en":"Che Guevara"},{"name":"Lula da Silva","emoji":"🔧","meta":["President of Brazil","Brazil","1945"],"description":"The Brazilian statesman, president of Brazil from 2003 to 2010 and again since 2023. Before he went into politics he worked as a metalworker and was one of the founders of the trade union movement and of the Workers' Party.","fact":"Lula da Silva grew up in extreme poverty and had no formal higher education before he became president of the country.","wiki_en":"Lula da Silva"},{"name":"Javier Milei","emoji":"📉","meta":["President of Argentina","Argentina","1970"],"description":"The Argentine economist and politician, president of Argentina since 2023. Before his election he worked as an economist and a television presenter, and he is known for his libertarian economic views and his sharp criticism of state spending.","fact":"Before he went into politics Milei was the singer in a rock band that played covers of The Rolling Stones.","wiki_en":"Javier Milei"},{"name":"Justin Trudeau","emoji":"🍁","meta":["former Prime Minister of Canada","Canada","1971"],"description":"The Canadian statesman, prime minister of Canada from 2015 to 2025, and son of the Canadian prime minister Pierre Trudeau. Before he went into politics he worked as a schoolteacher.","fact":"Justin Trudeau and his father Pierre are the only father-and-son pair in Canadian history both to have served as prime minister.","wiki_en":"Justin Trudeau"},{"name":"Mark Carney","emoji":"🏦","meta":["Prime Minister of Canada","Canada","1965"],"description":"The Canadian statesman and economist, prime minister of Canada since 2025. He previously headed the Bank of Canada, and then became the first person who was not a British subject to run the Bank of England, from 2013 to 2020.","fact":"Before he entered politics, Carney became the first person to have headed the central banks of two different G7 countries.","wiki_en":"Mark Carney"},{"name":"Kassym-Jomart Tokayev","emoji":"🐎","meta":["President of Kazakhstan","Kazakhstan","1953"],"description":"The Kazakh statesman and diplomat, president of Kazakhstan since 2019. Before reaching the top office he spent a long time in the diplomatic service, including UN bodies, and he speaks both Chinese and English.","fact":"From 2011 to 2013 Tokayev headed the United Nations Office at Geneva.","wiki_en":"Kassym-Jomart Tokayev"},{"name":"Nursultan Nazarbayev","emoji":"🏜️","meta":["former President of Kazakhstan","Kazakhstan","1940"],"description":"The Kazakh statesman, the first president of independent Kazakhstan, in office from 1991 to 2019. On his initiative the country's capital was moved from Alma-Ata to a city that was later named after him.","fact":"After voluntarily stepping down as president in 2019, Nazarbayev kept the title Elbasy, meaning leader of the nation.","wiki_en":"Nursultan Nazarbayev"},{"name":"Ilham Aliyev","emoji":"🏙️","meta":["President of Azerbaijan","Azerbaijan","1961"],"description":"The Azerbaijani statesman, president of Azerbaijan since 2003 and son of the country's previous president, Heydar Aliyev. Before coming to power he studied and taught at the Moscow State Institute of International Relations, and then worked at Azerbaijan's state oil company.","fact":"Since the end of the 1990s Aliyev has headed the National Olympic Committee of Azerbaijan.","wiki_en":"Ilham Aliyev"},{"name":"Nikol Pashinyan","emoji":"📰","meta":["Prime Minister of Armenia","Armenia","1975"],"description":"The Armenian statesman, prime minister of Armenia since 2018. He came to power after the mass protests known as the Velvet Revolution; before that he worked as a journalist and served as a member of parliament.","fact":"Before he moved into front-line politics Pashinyan edited an opposition newspaper and was prosecuted more than once.","wiki_en":"Nikol Pashinyan"},{"name":"Julius Caesar","emoji":"🗡️","meta":["Roman general and dictator","Ancient Rome","100–44 BC"],"description":"The Roman general and statesman, dictator of Rome, known for the conquest of Gaul and for his victory in the civil war against Pompey. He was killed by a group of conspirators from the Senate on the Ides of March in 44 BC.","fact":"The Julian calendar, introduced under Caesar, was the basis of European timekeeping for more than fifteen hundred years.","wiki_en":"Julius Caesar"},{"name":"Alexander the Great","emoji":"🐴","meta":["King of Macedon","Ancient Macedonia","356–323 BC"],"description":"King of Macedon, who built one of the largest empires of the ancient world, stretching from Greece to India. He came to the throne at twenty and, in a decade of campaigning, never lost a single major battle.","fact":"Alexander the Great died in Babylon at thirty-two, and the exact cause of his death is still argued over by historians.","wiki_en":"Alexander the Great"},{"name":"Genghis Khan","emoji":"🏹","meta":["founder of the Mongol Empire","Mongolia","c. 1162–1227"],"description":"The founder and first great khan of the Mongol Empire, who united the scattered Mongol tribes and built a state that became the largest contiguous land empire in history. His campaigns of conquest covered much of Asia.","fact":"The exact burial place of Genghis Khan has still not been found; legend says it was deliberately hidden from outsiders.","wiki_en":"Genghis Khan"},{"name":"Cleopatra","emoji":"🐍","meta":["Queen of Egypt","Ancient Egypt","69–30 BC"],"description":"The last queen of Hellenistic Egypt, from the Ptolemaic dynasty, who ruled jointly with her brothers and then her son. She is known for her alliances with the Roman generals Julius Caesar and Mark Antony, and took her own life after her defeat by Octavian.","fact":"Legend has it that Cleopatra killed herself by letting a venomous snake bite her, though the exact circumstances of her death are unknown.","wiki_en":"Cleopatra"},{"name":"George Clooney","emoji":"🎬","meta":["actor and director","United States","b. 1961"],"description":"The Hollywood actor who became a byword for male charm in the 1990s and 2000s, through the series \"ER\" and the \"Ocean's\" trilogy. He later turned to directing and producing, and won an Oscar as producer of \"Argo\".","fact":"Clooney has two Oscars of different kinds: as a supporting actor for \"Syriana\" and as producer of \"Argo\".","wiki_en":"George Clooney"},{"name":"Matt Damon","emoji":"🎭","meta":["actor and screenwriter","United States","b. 1970"],"description":"The actor who made his name in \"Good Will Hunting\", a script he wrote with Ben Affleck when they were both very young. He played the agent Jason Bourne in the franchise of that name and has appeared in dozens of major Hollywood films.","fact":"Damon and Affleck began writing the \"Good Will Hunting\" script while they were still students, and won an Oscar for it.","wiki_en":"Matt Damon"},{"name":"Ben Affleck","emoji":"🎥","meta":["actor and director","United States","b. 1972"],"description":"The actor and director who first broke through as a screenwriter, alongside his childhood friend Matt Damon. He played the superhero Batman in the DC film universe, and as director and producer of \"Argo\" he won the Oscar for best picture.","fact":"Before they became Hollywood stars, Affleck and Damon grew up as neighbours in Cambridge, Massachusetts.","wiki_en":"Ben Affleck"},{"name":"Mark Wahlberg","emoji":"💪","meta":["actor and producer","United States","b. 1971"],"description":"He started out as a rapper and an underwear model, and then became one of the most in-demand actors in Hollywood. He has appeared in \"The Fighter\", \"Ted\" and Martin Scorsese's films, \"The Departed\" among them.","fact":"Before he made his name as an actor, Wahlberg was the front man of the group Marky Mark and the Funky Bunch.","wiki_en":"Mark Wahlberg"},{"name":"Heath Ledger","emoji":"🃏","meta":["actor","Australia","1979–2008"],"description":"The Australian actor who became known worldwide after \"Brokeback Mountain\". He was awarded a posthumous Oscar for the Joker in \"The Dark Knight\", a performance that became one of the best-known screen versions of the character.","fact":"Ledger is one of very few actors to have received a posthumous Oscar for a film role.","wiki_en":"Heath Ledger"},{"name":"Edward Norton","emoji":"🥊","meta":["actor and director","United States","b. 1969"],"description":"The actor whose debut in \"Primal Fear\" brought him an Oscar nomination straight away. He is known for \"Fight Club\" and \"American History X\", as well as for his work as a director and screenwriter.","fact":"For his debut role in \"Primal Fear\", Norton won a Golden Globe and an Oscar nomination.","wiki_en":"Edward Norton"},{"name":"Gary Oldman","emoji":"🎩","meta":["actor","United Kingdom","b. 1958"],"description":"The British actor known for disappearing into wildly different roles, from Sirius Black in Harry Potter to Dracula and Churchill. For Winston Churchill in \"Darkest Hour\" he won the Oscar.","fact":"Oldman's roles include Beethoven, the musician Sid Vicious and Winston Churchill, and only the last of them brought him an Oscar.","wiki_en":"Gary Oldman"},{"name":"Harrison Ford","emoji":"🤠","meta":["actor","United States","b. 1942"],"description":"One of the highest-grossing actors in the history of Hollywood, famous as Han Solo in \"Star Wars\" and as the archaeologist Indiana Jones. Before his acting career he worked as a carpenter, which saw him through the years of obscurity.","fact":"Ford got the part of Han Solo after helping George Lucas read lines at other actors' auditions.","wiki_en":"Harrison Ford"},{"name":"Clint Eastwood","emoji":"🤠","meta":["actor and director","United States","b. 1930"],"description":"A legend of the western, who made his name as the Man with No Name in Sergio Leone's spaghetti westerns. As a director he has twice won the Oscar for best picture, for \"Unforgiven\" and \"Million Dollar Baby\".","fact":"After the age of seventy Eastwood made more than a dozen films, among them \"Million Dollar Baby\" and \"Gran Torino\".","wiki_en":"Clint Eastwood"},{"name":"Sean Connery","emoji":"🕴️","meta":["actor","United Kingdom","1930–2020"],"description":"The Scottish actor who was the first to play James Bond on screen and set the shape of agent 007 for decades. He later won an Oscar for \"The Untouchables\" and kept working into old age.","fact":"In 1989 People magazine named Connery the sexiest man alive, and ten years later the sexiest man of the century.","wiki_en":"Sean Connery"},{"name":"Pierce Brosnan","emoji":"🕶️","meta":["actor","Ireland","b. 1953"],"description":"The Irish actor who played James Bond in four films in the 1990s and 2000s, after his success in the series \"Remington Steele\". He has also appeared in the musical \"Mamma Mia!\" and in a long run of dramas.","fact":"Brosnan had already been considered for 007 back in the 1980s, but a television contract stood in the way.","wiki_en":"Pierce Brosnan"},{"name":"Daniel Craig","emoji":"🔫","meta":["actor","United Kingdom","b. 1968"],"description":"The British actor who played James Bond in five films, starting with \"Casino Royale\", and gave the character a harder, more realistic edge. He is also known as the detective in the \"Knives Out\" films.","fact":"Craig was the first blond actor to play Bond, which caused arguments among fans of the franchise at first.","wiki_en":"Daniel Craig"},{"name":"Hugh Grant","emoji":"💼","meta":["actor","United Kingdom","b. 1960"],"description":"The British actor who made his name in the romantic comedies \"Love Actually\" and \"Bridget Jones's Diary\". His charming, slightly diffident gentleman became one of the most recognisable faces of the genre.","fact":"Grant played the British prime minister in \"Love Actually\", dancing to music along the corridors of Downing Street.","wiki_en":"Hugh Grant"},{"name":"Mel Gibson","emoji":"⚔️","meta":["actor and director","United States","b. 1956"],"description":"The actor who made his name in \"Mad Max\" and the \"Lethal Weapon\" series. As a director he made the historical dramas \"Braveheart\" and \"The Passion of the Christ\", and won an Oscar for the first of them.","fact":"For \"Braveheart\", Gibson received the Oscar both as the film's director and as its producer.","wiki_en":"Mel Gibson"},{"name":"John Travolta","emoji":"🕺","meta":["actor","United States","b. 1954"],"description":"The actor who became a star through the dance films \"Saturday Night Fever\" and \"Grease\", and who then, decades later, saw his career take off all over again after Tarantino's \"Pulp Fiction\".","fact":"The dance by Travolta and Uma Thurman in \"Pulp Fiction\" became one of the most parodied scenes in film history.","wiki_en":"John Travolta"},{"name":"Vin Diesel","emoji":"🚗","meta":["actor","United States","b. 1967"],"description":"The actor and producer known above all as Dominic Toretto in the \"Fast & Furious\" franchise, which became one of the highest-grossing series in film history. He also voiced Groot in the \"Guardians of the Galaxy\" films.","fact":"Groot's line barely changes — \"I am Groot\" — but Diesel also recorded it for several foreign-language dubs.","wiki_en":"Vin Diesel"},{"name":"Jason Statham","emoji":"🥋","meta":["actor","United Kingdom","b. 1967"],"description":"The British actor who specialises in action films and made his name in Guy Ritchie's \"Lock, Stock and Two Smoking Barrels\" and \"Snatch\". He is known for the \"Transporter\" and \"Fast & Furious\" franchises.","fact":"Before his acting career Statham spent years as a diver and competed for the British national team.","wiki_en":"Jason Statham"},{"name":"Liam Neeson","emoji":"📞","meta":["actor","Ireland","b. 1952"],"description":"The Irish actor known as Oskar Schindler in Spielberg's \"Schindler's List\", who in later life became an action star thanks to the \"Taken\" films, an unlikely second career that began in his fifties.","fact":"Neeson's line from \"Taken\" about a \"particular set of skills\" became one of the most quoted in 2000s cinema.","wiki_en":"Liam Neeson"},{"name":"Marlon Brando","emoji":"🎞️","meta":["actor","United States","1924–2004"],"description":"One of the most influential actors of the twentieth century, who changed the way film acting was done with his natural, psychologically truthful manner. He made his name in \"A Streetcar Named Desire\" and as Don Corleone in \"The Godfather\".","fact":"Brando won the Oscar for \"The Godfather\" but refused it in protest, sending a Native American woman to the ceremony in his place.","wiki_en":"Marlon Brando"},{"name":"Paul Newman","emoji":"🏎️","meta":["actor","United States","1925–2008"],"description":"The actor with the piercing blue eyes, the star of \"Cool Hand Luke\" and \"The Sting\", and a keen racing driver. He founded the food company Newman's Own, arranging for all of its profits to go to charity.","fact":"Newman raced seriously: in 1979 his crew finished second at the 24 Hours of Le Mans.","wiki_en":"Paul Newman"},{"name":"Kate Winslet","emoji":"💎","meta":["actress","United Kingdom","b. 1975"],"description":"The British actress who became famous as Rose in James Cameron's \"Titanic\". An Oscar winner for \"The Reader\", she is also known for \"Eternal Sunshine of the Spotless Mind\" and for her work in television series.","fact":"Winslet won her Oscar only on the sixth attempt: before \"The Reader\" she had been nominated five times without winning.","wiki_en":"Kate Winslet"},{"name":"Charlize Theron","emoji":"🔥","meta":["actress","South Africa","b. 1975"],"description":"The South African-born actress who won an Oscar for her physically transformed performance as a serial killer in \"Monster\". She is also known for the action films \"Mad Max: Fury Road\" and \"Atomic Blonde\".","fact":"Theron was the first actress from South Africa to win an Oscar for acting.","wiki_en":"Charlize Theron"},{"name":"Halle Berry","emoji":"🌟","meta":["actress","United States","b. 1966"],"description":"The actress who became the first Black woman to win the Oscar for best actress, for \"Monster's Ball\". She is also known as Storm in the \"X-Men\" franchise and as the agent Jinx in the Bond films.","fact":"Accepting her Oscar, Berry dedicated the award to Dorothy Dandridge, Lena Horne and other Black actresses of the past.","wiki_en":"Halle Berry"},{"name":"Uma Thurman","emoji":"🗡️","meta":["actress","United States","b. 1970"],"description":"The actress best known for her work with the director Quentin Tarantino, in \"Pulp Fiction\" and the two \"Kill Bill\" films. She began her film career as a teenager at the end of the 1980s.","fact":"Tarantino wrote the Bride in \"Kill Bill\" specifically for Thurman, talking the story through with her while they were shooting \"Pulp Fiction\".","wiki_en":"Uma Thurman"},{"name":"Cameron Diaz","emoji":"😄","meta":["actress","United States","b. 1972"],"description":"The actress who made her film debut as a model with no acting experience, in \"The Mask\" with Jim Carrey. She became a star of the comedies \"There's Something About Mary\" and \"Charlie's Angels\", and voiced Princess Fiona in the \"Shrek\" films.","fact":"\"The Mask\" was Diaz's first acting job of any kind: until then she had worked only as a model.","wiki_en":"Cameron Diaz"},{"name":"Reese Witherspoon","emoji":"💗","meta":["actress and producer","United States","b. 1976"],"description":"The actress who won an Oscar for playing the singer June Carter in the biopic \"Walk the Line\". She also made her name in the comedy \"Legally Blonde\", and later became a successful producer, adapting books for television.","fact":"Witherspoon founded a production company that has adapted a long list of bestsellers, including the series \"Big Little Lies\".","wiki_en":"Reese Witherspoon"},{"name":"Gwyneth Paltrow","emoji":"🍏","meta":["actress and entrepreneur","United States","b. 1972"],"description":"The actress who won an Oscar for \"Shakespeare in Love\" and played Pepper Potts in the Marvel Cinematic Universe. She later moved into business, founding the lifestyle goods company Goop.","fact":"Paltrow played Pepper Potts for more than ten years, from the first \"Iron Man\" to \"Avengers: Endgame\".","wiki_en":"Gwyneth Paltrow"},{"name":"Penélope Cruz","emoji":"💃","meta":["actress","Spain","b. 1974"],"description":"The Spanish actress who was the first from her country to win an Oscar, for Woody Allen's \"Vicky Cristina Barcelona\". She has worked often with Pedro Almodóvar and on Hollywood projects, among them \"Pirates of the Caribbean\".","fact":"Cruz has also been nominated for Oscars for roles in Spanish, in Almodóvar's \"Volver\" and \"Parallel Mothers\".","wiki_en":"Penélope Cruz"},{"name":"Salma Hayek","emoji":"🌺","meta":["actress and producer","Mexico","b. 1966"],"description":"The Mexican actress who became known worldwide for the biopic \"Frida\", which brought her an Oscar nomination. She appeared in \"Desperado\" and \"From Dusk till Dawn\", and later moved into producing.","fact":"Hayek not only starred in \"Frida\" but also produced it, spending years pushing to get the film made.","wiki_en":"Salma Hayek"},{"name":"Helen Mirren","emoji":"👑","meta":["actress","United Kingdom","b. 1945"],"description":"The British actress who won an Oscar for playing Elizabeth II in \"The Queen\". She is known for an extraordinary range, from detective series about Inspector Jane Tennison to large-scale Hollywood productions.","fact":"Mirren played two queens in a row: Elizabeth I in a television mini-series and Elizabeth II in \"The Queen\".","wiki_en":"Helen Mirren"},{"name":"Judi Dench","emoji":"🎓","meta":["actress","United Kingdom","b. 1934"],"description":"The British stage and screen actress, for many years M in the James Bond films. She won an Oscar for \"Shakespeare in Love\", despite being on screen for no more than a few minutes. Her career has run from Shakespeare on stage to blockbusters.","fact":"Dench's role in \"Shakespeare in Love\" lasts about eight minutes on screen, and still won her an Oscar.","wiki_en":"Judi Dench"},{"name":"Cate Blanchett","emoji":"🧝","meta":["actress","Australia","b. 1969"],"description":"The Australian actress and a double Oscar winner, for \"The Aviator\" and \"Blue Jasmine\". She is known for turning into Galadriel in \"The Lord of the Rings\" and Elizabeth I in the historical drama of that name.","fact":"Blanchett played the real actress Katharine Hepburn in \"The Aviator\", and that is what won her her first Oscar.","wiki_en":"Cate Blanchett"},{"name":"Sophia Loren","emoji":"🌹","meta":["actress","Italy","b. 1934"],"description":"The Italian actress, one of the icons of mid-twentieth-century European cinema, who won an Oscar for \"Two Women\", a rare award for a performance not in English. She appeared alongside Marcello Mastroianni in dozens of films.","fact":"Thirty years after \"Two Women\", Loren received a second Oscar, an honorary one, for her contribution to cinema.","wiki_en":"Sophia Loren"},{"name":"Elizabeth Taylor","emoji":"💜","meta":["actress","United Kingdom / United States","1932–2011"],"description":"One of the biggest stars of classical Hollywood, she began acting as a child and became famous for \"Cleopatra\" and \"Who's Afraid of Virginia Woolf?\", which won her an Oscar. She was also known for her violet eyes and her jewellery collection.","fact":"Taylor twice won the Oscar for best actress, for \"BUtterfield 8\" and \"Who's Afraid of Virginia Woolf?\".","wiki_en":"Elizabeth Taylor"},{"name":"Grace Kelly","emoji":"👸","meta":["actress","United States / Monaco","1929–1982"],"description":"The Hollywood actress who won an Oscar for \"The Country Girl\" and then left the cinema to marry Prince Rainier III of Monaco and take the title of princess. She appeared in several of Alfred Hitchcock's films.","fact":"After her wedding to the prince of Monaco, Kelly gave up acting and never appeared in a film again.","wiki_en":"Grace Kelly"},{"name":"Peter Jackson","emoji":"💍","meta":["director","New Zealand","b. 1961"],"description":"The New Zealand director who filmed \"The Lord of the Rings\" trilogy, winning the Oscar for best director. He later made \"The Hobbit\" prequel trilogy and documentary projects, including restored footage of the First World War.","fact":"Jackson shot the whole \"Lord of the Rings\" trilogy at once rather than one film at a time, which was unusual at the time.","wiki_en":"Peter Jackson"},{"name":"Ridley Scott","emoji":"👽","meta":["director","United Kingdom","b. 1937"],"description":"The British director who made the landmark science fiction films \"Alien\" and \"Blade Runner\", as well as the historical drama \"Gladiator\", which brought him an Oscar nomination. He has kept working steadily in film for more than half a century.","fact":"Scott began his career directing advertisements, before he made his first feature film.","wiki_en":"Ridley Scott"},{"name":"Tim Burton","emoji":"🦇","meta":["director","United States","b. 1958"],"description":"The director with the unmistakable gothic style, behind \"Beetlejuice\" and \"Edward Scissorhands\", who devised and produced \"The Nightmare Before Christmas\". He works often with the actor Johnny Depp and the composer Danny Elfman.","fact":"Burton dreamed up \"The Nightmare Before Christmas\" while he was still working as an animator at Disney in the early 1980s.","wiki_en":"Tim Burton"},{"name":"David Fincher","emoji":"🔪","meta":["director","United States","b. 1962"],"description":"The director known for bleak, meticulously built thrillers: \"Se7en\", \"Fight Club\" and \"Zodiac\". He also made the biographical drama \"The Social Network\", which won several Oscars and became the defining film about the founding of Facebook.","fact":"Fincher is famous for demanding take after take on set, reshooting some scenes dozens of times to get exactly the result he wants.","wiki_en":"David Fincher"},{"name":"Guy Ritchie","emoji":"🎩","meta":["director","United Kingdom","b. 1968"],"description":"The British director who made his name with the fast-moving crime comedies \"Lock, Stock and Two Smoking Barrels\" and \"Snatch\". He later made the Hollywood Sherlock Holmes franchise with Robert Downey Jr. and the live-action remake of \"Aladdin\".","fact":"The success of Ritchie's debut, \"Lock, Stock and Two Smoking Barrels\", made him one of the most recognisable British directors of the 1990s.","wiki_en":"Guy Ritchie"},{"name":"Stanley Kubrick","emoji":"🌀","meta":["director","United States","1928–1999"],"description":"One of the most influential directors of the twentieth century, known for his perfectionism and for his range of genres, from the science fiction of \"2001: A Space Odyssey\" to the horror of \"The Shining\" and the war drama \"Full Metal Jacket\".","fact":"Kubrick reshot some scenes of \"The Shining\" more than a hundred times, pushing for exactly the result he wanted from his actors.","wiki_en":"Stanley Kubrick"},{"name":"Alfred Hitchcock","emoji":"🔪","meta":["director","United Kingdom","1899–1980"],"description":"The British director who went down in history as the master of suspense, on the strength of \"Psycho\", \"Vertigo\" and \"The Birds\". He worked out a whole set of techniques for building tension that are still in use in film today.","fact":"Hitchcock habitually turned up in short cameos in his own films, which became his recognisable signature.","wiki_en":"Alfred Hitchcock"},{"name":"George Lucas","emoji":"⭐","meta":["director","United States","b. 1944"],"description":"The creator of the \"Star Wars\" universe, which changed the business of special effects and film production alike. He founded the company Industrial Light & Magic, which became one of the leading visual effects houses in cinema.","fact":"Industrial Light & Magic, founded by Lucas to shoot \"Star Wars\", stands at the origin of modern computer special effects.","wiki_en":"George Lucas"},{"name":"James Gunn","emoji":"🦝","meta":["director","United States","b. 1966"],"description":"The director who made the \"Guardians of the Galaxy\" trilogy for Marvel and the superhero film \"The Suicide Squad\" for DC. He began his career writing scripts for low-budget films, before becoming one of the key directors of superhero cinema.","fact":"Before he moved to blockbusters, Gunn worked as a screenwriter on low-budget films for the independent horror studio Troma.","wiki_en":"James Gunn"},{"name":"Denis Villeneuve","emoji":"🏜️","meta":["director","Canada","b. 1967"],"description":"The Canadian director who won worldwide recognition with the science fiction films \"Arrival\" and \"Blade Runner 2049\" and his sweeping adaptation of \"Dune\". Before Hollywood he made auteur films at home in Quebec.","fact":"Long before he took on \"Dune\", Villeneuve had dreamed of filming Frank Herbert's novel, calling it his favourite book.","wiki_en":"Denis Villeneuve"},{"name":"Nikita Mikhalkov","emoji":"🎬","meta":["actor and director","Russia","b. 1945"],"description":"The Russian director and actor who won the Oscar for best foreign film with \"Burnt by the Sun\". He also made \"The Barber of Siberia\" and dozens of other films, playing the lead in a good many of them.","fact":"\"Burnt by the Sun\" was the first Russian film to win an Oscar after the break-up of the USSR.","wiki_en":"Nikita Mikhalkov"},{"name":"Oleg Tabakov","emoji":"🎭","meta":["actor and teacher","Russia / USSR","1935–2018"],"description":"The Soviet and Russian actor who ran the Chekhov Moscow Art Theatre for many years and brought up a whole generation of actors as a teacher. He appeared in films from the 1950s onwards; among his best-known parts is Matroskin in the Prostokvashino cartoons.","fact":"The studio theatre Tabakov created has long been known to audiences and actors alike by his surname, as the Tabakerka.","wiki_en":"Oleg Tabakov"},{"name":"Leonid Gaidai","emoji":"😂","meta":["director","USSR","1923–1993"],"description":"The Soviet director behind the cult comedies \"Kidnapping, Caucasian Style\", \"Ivan Vasilievich Changes Profession\" and \"The Diamond Arm\", classics that the whole country can quote. His films drew some of the largest audiences in the history of Soviet cinema.","fact":"Many lines from Gaidai's films, such as \"pity about the little bird\", have long since become fixed expressions in Russian.","wiki_en":"Leonid Gaidai"},{"name":"Eldar Ryazanov","emoji":"🎄","meta":["director","USSR / Russia","1927–2015"],"description":"The Soviet director behind the wry, warm comedies \"The Irony of Fate\", \"Office Romance\" and \"Beware of the Car\". His New Year film became an annual television tradition right across the post-Soviet world.","fact":"Since 1976 \"The Irony of Fate\" has been shown on television on New Year's Eve almost every single year.","wiki_en":"Eldar Ryazanov"},{"name":"Alexander Abdulov","emoji":"🎩","meta":["actor","USSR / Russia","1953–2008"],"description":"The Soviet and Russian actor of the Lenkom theatre and of the cinema, known for the films \"An Ordinary Miracle\" and \"The Formula of Love\". For many years he remained one of the most popular and recognisable actors of his generation.","fact":"Abdulov played many leading roles at the Lenkom, working with the director Mark Zakharov over several decades.","wiki_en":"Alexander Abdulov"},{"name":"Yevgeny Mironov","emoji":"🎭","meta":["actor","Russia","b. 1966"],"description":"The Russian stage and screen actor, artistic director of the Theatre of Nations. He is known for the films \"The Idiot\", \"The Muslim\" and \"The Age of Pioneers\", as well as for a great deal of work in the theatre.","fact":"His role in the television series \"The Idiot\", from Dostoevsky's novel, won him wide recognition as one of the finest dramatic actors of his generation.","wiki_en":"Yevgeny Mironov","wiki_ru":"Миронов, Евгений Витальевич"},{"name":"Sergei Garmash","emoji":"🎬","meta":["actor","Russia","b. 1958"],"description":"The Russian stage and screen actor, recognisable from the films \"Mama, Don't Cry\" and \"12\", and from his long years at the Sovremennik theatre. He is also known for his war and dramatic roles.","fact":"Garmash was born in Ukraine and trained as an actor at the theatre college in Dnepropetrovsk.","wiki_en":"Sergei Garmash"},{"name":"Fyodor Bondarchuk","emoji":"🎥","meta":["actor and director","Russia","b. 1967"],"description":"The Russian director and actor, son of the director Sergei Bondarchuk. He made \"9th Company\" and \"Stalingrad\", both notable events in Russian cinemas, and he also produces large film projects.","fact":"Bondarchuk is the son of the legendary Soviet director Sergei Bondarchuk, who made the Oscar-winning \"War and Peace\".","wiki_en":"Fyodor Bondarchuk"},{"name":"Vladimir Mashkov","emoji":"🎭","meta":["actor and director","Russia","b. 1963"],"description":"The Russian actor and director, artistic director of the Tabakerka theatre. He has worked in Hollywood, in \"Mission: Impossible – Ghost Protocol\" and \"15 Minutes\", and is known for his roles in Russian film and theatre.","fact":"In the Hollywood thriller \"15 Minutes\", Mashkov acted alongside Robert De Niro.","wiki_en":"Vladimir Mashkov"},{"name":"Chulpan Khamatova","emoji":"🎗️","meta":["actress","Russia","b. 1975"],"description":"The Russian stage and screen actress, known for the films \"The Country of the Deaf\" and \"Petrushka Syndrome\". She has also spent many years in charity work, as co-founder of a foundation for children with cancer.","fact":"Khamatova co-founded the charitable foundation Gift of Life, which helps children with cancer and blood disorders.","wiki_en":"Chulpan Khamatova"},{"name":"Lyudmila Gurchenko","emoji":"🎤","meta":["actress","USSR / Russia","1935–2011"],"description":"The Soviet and Russian actress and singer who became famous for the musical comedy \"Carnival Night\". She worked in film for more than half a century; among her best-known parts are \"Station for Two\" and \"Love and Doves\".","fact":"After the huge success of \"Carnival Night\", Gurchenko all but vanished from the screen for several years because of difficulties in her career.","wiki_en":"Lyudmila Gurchenko"},{"name":"Faina Ranevskaya","emoji":"🎭","meta":["actress","USSR","1896–1984"],"description":"The Soviet stage and screen actress, as well known for her sharp tongue and her aphorisms as for her roles. She appeared in \"The Foundling\" and \"Spring\", and her line \"Mulya, don't get on my nerves\" stayed in the language for decades.","fact":"By a well-known story, Leonid Brezhnev greeted the actress at an awards ceremony with her own line about Mulya.","wiki_en":"Faina Ranevskaya"},{"name":"Vladimir Pozner","emoji":"🎙️","meta":["journalist and television host","Russia / France","b. 1934"],"description":"The journalist and television presenter who worked for many years on Soviet and Russian television, and in the United States as well. He is known for his own programme \"Pozner\" and for the USSR–US space bridges of the 1980s.","fact":"Pozner was born in Paris and spent his childhood in the United States, before his family moved to the USSR.","wiki_en":"Vladimir Pozner","wiki_ru":"Познер, Владимир Владимирович"},{"name":"Andrey Malakhov","emoji":"🎙️","meta":["television host","Russia","b. 1972"],"description":"The Russian television presenter who spent many years on the federal channels, and who created the talk shows \"Let Them Talk\" and \"Malakhov\". He is one of the most recognisable talk show hosts on Russian television.","fact":"Malakhov presented \"Let Them Talk\" for more than ten years, making it one of the most talked-about shows in the country.","wiki_en":"Andrey Malakhov"},{"name":"Dmitry Nagiev","emoji":"😎","meta":["actor and television host","Russia","b. 1967"],"description":"The Russian actor and presenter who became known as the host of the programme \"Windows\" and the show \"The Voice\", and as the star of the series \"PE Teacher\". He mixes comic and dramatic roles in film.","fact":"Long before \"PE Teacher\", Nagiev appeared in the St Petersburg comedy sketch series \"Careful, Modern!\".","wiki_en":"Dmitry Nagiev"},{"name":"Maxim Galkin","emoji":"🎤","meta":["comedian and television host","Russia","b. 1976"],"description":"The Russian variety artist, impressionist and television presenter, known for a great many comic turns and for his impersonations of politicians and celebrities. He has also hosted several television shows.","fact":"Galkin hosted the Russian version of the quiz show \"Who Wants to Be a Millionaire?\" for many years.","wiki_en":"Maxim Galkin"},{"name":"Ksenia Sobchak","emoji":"🎤","meta":["television host and journalist","Russia","b. 1981"],"description":"The Russian television presenter and journalist who began her career on the reality show \"Dom-2\" and later turned to investigative journalism and public activity. She is the daughter of the first mayor of Saint Petersburg, Anatoly Sobchak.","fact":"Sobchak is the daughter of Anatoly Sobchak, the first mayor of Saint Petersburg, for whom Vladimir Putin once worked.","wiki_en":"Ksenia Sobchak"},{"name":"Anastasia Ivleeva","emoji":"📱","meta":["blogger and television host","Russia","b. 1993"],"description":"The Russian blogger and television presenter who became known through comic videos on social media and by hosting the show \"Heads and Tails\". She is one of the most popular Russian-language internet personalities of her generation.","fact":"Ivleeva started out making short comic clips on social media, before she became a television presenter.","wiki_en":"Anastasia Ivleeva"},{"name":"Yevgeny Leonov","emoji":"🐻","meta":["actor","USSR","1926–1994"],"description":"The Soviet actor with a uniquely good-natured charm, who played dozens of much-loved parts in films such as \"Gentlemen of Fortune\" and \"Autumn Marathon\". He voiced Winnie-the-Pooh in the Soviet animated trilogy.","fact":"To make Winnie-the-Pooh sound higher, Leonov's recorded voice was speeded up slightly in the edit.","wiki_en":"Yevgeny Leonov"},{"name":"Nonna Mordyukova","emoji":"🎬","meta":["actress","USSR","1925–2008"],"description":"The Soviet actress who became famous for \"The Young Guard\" while she was still a student, and then played the memorable building manager in the comedy \"The Diamond Arm\", along with dozens of other roles in Soviet cinema.","fact":"The drama \"The Commissar\", with Mordyukova in the lead, sat on the shelf for about twenty years and only reached audiences in 1987.","wiki_en":"Nonna Mordyukova"},{"name":"Ellen DeGeneres","emoji":"😊","meta":["television host and comedian","United States","b. 1958"],"description":"The American comedian and television host who presented her own daytime talk show, \"The Ellen DeGeneres Show\", for many years. She is also known as the voice of the fish Dory in \"Finding Nemo\" and \"Finding Dory\".","fact":"DeGeneres voiced Dory in two Pixar films, both of which became among the highest-grossing animated films ever made.","wiki_en":"Ellen DeGeneres"},{"name":"Jimmy Kimmel","emoji":"🎙️","meta":["television host","United States","b. 1967"],"description":"The American television host who has fronted the late-night show \"Jimmy Kimmel Live!\" for many years and has presented the Oscars ceremony more than once. He is one of the most prominent talk show hosts on American television.","fact":"Kimmel has hosted the Oscars several times, one of the few presenters invited back to the ceremony again and again.","wiki_en":"Jimmy Kimmel"},{"name":"Simon Cowell","emoji":"👔","meta":["producer and television host","United Kingdom","b. 1959"],"description":"The British music producer and television host, known as the severe judge on the talent shows \"The X Factor\" and \"Britain's Got Talent\", as well as on the American show \"American Idol\". He launched the careers of many pop performers.","fact":"Cowell became famous for blunt but honest verdicts on contestants, which turned into his signature style of judging on talent shows.","wiki_en":"Simon Cowell"},{"name":"Logan Paul","emoji":"📹","meta":["YouTuber","United States","b. 1995"],"description":"The American video blogger who started out on the Vine platform and then became one of the most popular creators on YouTube. He later took up boxing, fought several high-profile bouts, and became co-owner of the drink Prime.","fact":"Paul launched the Prime line of drinks together with the blogger KSI, whom he had previously met twice in the ring.","wiki_en":"Logan Paul"},{"name":"Jake Paul","emoji":"🥊","meta":["YouTuber and boxer","United States","b. 1997"],"description":"The American video blogger and boxer, the younger brother of Logan Paul, who began his career on social media and on Vine. He has fought a string of boxing matches against bloggers and professional boxers alike.","fact":"Paul built a second career as a professional boxer, fighting former champions in several different weight classes.","wiki_en":"Jake Paul"},{"name":"KSI","emoji":"🎮","meta":["YouTuber and musician","United Kingdom","b. 1993"],"description":"The British video blogger, real name Olajide Olatunji, who started out with videos about the football game FIFA on YouTube. He later took up music and boxing, and became co-owner of the drink Prime.","fact":"Besides his videos, KSI makes music and has put several of his singles into the British charts.","wiki_en":"KSI"},{"name":"Ninja","emoji":"🎮","meta":["streamer","United States","b. 1991"],"description":"The American esports player and streamer, real name Tyler Blevins, who made his name broadcasting the game Fortnite. He was one of the first streamers to become a widely recognised media figure outside the gaming world.","fact":"Ninja's joint Fortnite stream with the rapper Drake in 2018 became one of the most watched in the history of the Twitch platform.","wiki_en":"Ninja (streamer)"},{"name":"Jay Leno","emoji":"🚗","meta":["television host and comedian","United States","b. 1950"],"description":"The American comedian who hosted the popular late-night programme \"The Tonight Show\" for many years, and who is also known for a huge collection of cars and motorcycles, the subject of a show of his own.","fact":"Leno's garage holds about two hundred cars, among them steam-powered machines from the early twentieth century.","wiki_en":"Jay Leno"},{"name":"Warren Buffett","emoji":"💰","meta":["investor","United States","b. 1930"],"description":"The American investor and long-time head of the investment holding company Berkshire Hathaway, known for his long-term approach to putting money to work. One of the wealthiest people in the world, he has lived for years in a modest house in Omaha.","fact":"Buffett has lived in the same house in Omaha for many decades, having bought it back in 1958.","wiki_en":"Warren Buffett"},{"name":"Richard Branson","emoji":"🚀","meta":["entrepreneur","United Kingdom","b. 1950"],"description":"The British entrepreneur and founder of the Virgin Group conglomerate, which takes in an airline, a record label and the space company Virgin Galactic. He is known for bold marketing stunts and for record-breaking journeys.","fact":"Branson flew into space aboard a craft built by his own company, Virgin Galactic, in 2021.","wiki_en":"Richard Branson"},{"name":"Rupert Murdoch","emoji":"📰","meta":["media mogul","Australia / United States","b. 1931"],"description":"The Australian-born media mogul, founder of News Corporation and owner of a great many newspapers and television channels, Fox News among them. One of the most influential figures in the world media industry of the later twentieth century.","fact":"Murdoch started out with a single Australian newspaper inherited from his father, and went on to build one of the largest media groups in the world.","wiki_en":"Rupert Murdoch"},{"name":"Henry Ford","emoji":"🚗","meta":["entrepreneur","United States","1863–1947"],"description":"The founder of the Ford Motor Company, who introduced assembly-line production of cars and with it put motoring within reach of ordinary buyers. The Ford Model T became one of the symbols of the industrial age.","fact":"Thanks to the assembly line, building a single Ford Model T sped up from about twelve hours to an hour and a half.","wiki_en":"Henry Ford"},{"name":"John D. Rockefeller","emoji":"🛢️","meta":["entrepreneur","United States","1839–1937"],"description":"The founder of the oil company Standard Oil, who became one of the richest people in history. In the second half of his life he turned to philanthropy on a huge scale, setting up a foundation in his own name.","fact":"Rockefeller's fortune, converted into today's money, is reckoned one of the largest personal fortunes in history.","wiki_en":"John D. Rockefeller"},{"name":"Walt Disney","emoji":"🐭","meta":["entrepreneur and animator","United States","1901–1966"],"description":"The American animator and businessman who created Mickey Mouse and founded the Walt Disney studio, which became one of the largest entertainment companies in the world. He opened the first theme park, Disneyland, in 1955.","fact":"Disney personally voiced Mickey Mouse in the studio's early cartoons, for almost two decades.","wiki_en":"Walt Disney"},{"name":"Larry Page","emoji":"🔍","meta":["entrepreneur","United States","b. 1973"],"description":"Co-founder of Google, who worked out the PageRank search algorithm together with Sergey Brin while he was still a graduate student at Stanford. For a long time he ran the parent company, Alphabet.","fact":"The name of PageRank, the algorithm at the heart of Google search, comes from Page's own surname.","wiki_en":"Larry Page"},{"name":"Sergey Brin","emoji":"🔍","meta":["entrepreneur","United States","b. 1973"],"description":"Co-founder of Google, born in Moscow and brought to the United States by his family as a child. Together with Larry Page he built the search engine while the two of them were studying at Stanford University.","fact":"Brin moved to the United States from the USSR with his parents at the age of six.","wiki_en":"Sergey Brin"},{"name":"Tim Cook","emoji":"🍎","meta":["entrepreneur","United States","b. 1960"],"description":"The chief executive of Apple, who took over the post from Steve Jobs in 2011. Before that he spent many years in charge of the company's operations and supply chains, the unglamorous machinery behind every launch.","fact":"Cook was one of the first chief executives of a major US corporation to speak openly about being gay.","wiki_en":"Tim Cook"},{"name":"Jack Ma","emoji":"🛒","meta":["entrepreneur","China","b. 1964"],"description":"The Chinese entrepreneur who founded the Alibaba Group, one of the largest e-commerce platforms in the world. Before his success in business he worked as a teacher of English in his home city.","fact":"Before he founded Alibaba, Ma tried and failed to get various jobs, including one at a KFC restaurant.","wiki_en":"Jack Ma"},{"name":"Roman Abramovich","emoji":"⚽","meta":["entrepreneur","Russia","b. 1966"],"description":"The Russian businessman who grew rich in the oil and metals industries in the 1990s. For a long time he owned the English football club Chelsea, which he turned into one of the leading clubs in Europe.","fact":"Under Abramovich's ownership, Chelsea won the UEFA Champions League for the first time in the club's history.","wiki_en":"Roman Abramovich"},{"name":"Mikhail Khodorkovsky","emoji":"🛢️","meta":["entrepreneur","Russia","b. 1963"],"description":"The Russian businessman who in the 1990s came to head the oil company Yukos, one of the largest in the country. In 2003 he was arrested and convicted in a case of fraud and tax evasion, and spent ten years in prison.","fact":"After his release in 2013, Khodorkovsky left Russia and took up public and publishing work.","wiki_en":"Mikhail Khodorkovsky"},{"name":"German Gref","emoji":"🏦","meta":["entrepreneur","Russia","b. 1964"],"description":"The Russian statesman and businessman who served as minister of economic development in the 2000s and then took charge of the country's largest bank, Sberbank. He runs a sweeping digital transformation of the bank.","fact":"Under Gref's leadership Sberbank turned from a traditional bank into a large technology ecosystem of services.","wiki_en":"German Gref"},{"name":"Alisher Usmanov","emoji":"🏭","meta":["entrepreneur","Uzbekistan / Russia","b. 1953"],"description":"The businessman who began his career in the metals industry and later invested in telecommunications and technology companies. For a long time he was known for his investments in European football and for large holdings in mining and metals.","fact":"Usmanov held a large stake in the English club Arsenal for many years, and sold it in 2018.","wiki_en":"Alisher Usmanov"},{"name":"Coco Chanel","emoji":"👗","meta":["fashion designer","France","1883–1971"],"description":"The French fashion designer and founder of the house of Chanel, who changed women's fashion in the twentieth century by freeing it from corsets and heavy fabrics. She created the famous scent Chanel No. 5 and the little black dress.","fact":"Chanel No. 5, launched in 1921, is still one of the best-selling perfumes in the world.","wiki_en":"Coco Chanel"},{"name":"Albert Einstein","emoji":"🧠","meta":["physicist","Germany / United States","1879–1955"],"description":"The theoretical physicist who created the theory of relativity, changing how humanity understands space, time and gravity. He won the Nobel Prize in Physics for his explanation of the photoelectric effect.","fact":"Einstein received the Nobel Prize not for relativity but for his explanation of the photoelectric effect.","wiki_en":"Albert Einstein"},{"name":"Isaac Newton","emoji":"🍎","meta":["physicist and mathematician","England","1643–1727"],"description":"The English scientist who set out the laws of classical mechanics and the law of universal gravitation, and who also made a fundamental contribution to mathematics by laying the foundations of differential calculus.","fact":"Legend has it that the idea of universal gravitation came to Newton from an apple falling off a tree.","wiki_en":"Isaac Newton"},{"name":"Charles Darwin","emoji":"🐒","meta":["naturalist","United Kingdom","1809–1882"],"description":"The English naturalist who developed the theory of evolution by natural selection, set out in \"On the Origin of Species\". He gathered the key observations for it during a voyage around the world aboard the ship Beagle.","fact":"\"On the Origin of Species\" came out more than twenty years after the voyage: Darwin took a long time to nerve himself to publish.","wiki_en":"Charles Darwin"},{"name":"Nikola Tesla","emoji":"⚡","meta":["inventor and engineer","Austria-Hungary / United States","1856–1943"],"description":"The engineer and inventor of Serbian descent who made a key contribution to the development of alternating current technology. He worked on the wireless transmission of energy and held hundreds of patents in different fields of engineering.","fact":"Tesla spent years competing with Thomas Edison over which current, alternating or direct, would become the standard for electricity supply.","wiki_en":"Nikola Tesla"},{"name":"Thomas Edison","emoji":"💡","meta":["inventor","United States","1847–1931"],"description":"The American inventor and businessman who improved the incandescent lamp and created the phonograph. He set up a research laboratory that became the model for modern research and development centres.","fact":"More than a thousand patents for inventions in all kinds of fields of engineering are registered in Edison's name.","wiki_en":"Thomas Edison"},{"name":"Marie Curie","emoji":"☢️","meta":["physicist and chemist","Poland / France","1867–1934"],"description":"The physicist and chemist of Polish origin, the first woman to win a Nobel Prize and the only person to have won Nobel Prizes in two different sciences, physics and chemistry. She discovered the radioactive elements polonium and radium.","fact":"Curie's daughter became a Nobel laureate too: Irène Joliot-Curie received the prize for chemistry in 1935.","wiki_en":"Marie Curie"},{"name":"Stephen Hawking","emoji":"🌌","meta":["physicist","United Kingdom","1942–2018"],"description":"The British theoretical physicist who studied black holes and the origin of the universe, and wrote the bestseller \"A Brief History of Time\". Despite a serious illness that paralysed his body, he went on with his scientific work using a speech synthesiser.","fact":"Hawking lived for more than half a century with motor neurone disease, diagnosed when he was young, far outlasting the usual prognosis.","wiki_en":"Stephen Hawking"},{"name":"Galileo Galilei","emoji":"🔭","meta":["astronomer and physicist","Italy","1564–1642"],"description":"The Italian scientist who improved the telescope and used it to discover the moons of Jupiter, the phases of Venus and mountains on the Moon. He defended the heliocentric model of the world, and was persecuted by the church for it.","fact":"The moons of Jupiter that Galileo discovered are still called the Galilean moons in his honour.","wiki_en":"Galileo Galilei"},{"name":"Dmitri Mendeleev","emoji":"🧪","meta":["chemist","Russia","1834–1907"],"description":"The Russian chemist who created the periodic system of the chemical elements, the foundation of modern chemistry. He predicted the existence and the properties of elements that had not yet been discovered, from the patterns in his own table.","fact":"Mendeleev was interested in ballooning too: in 1887 he went up in a balloon to observe a solar eclipse.","wiki_en":"Dmitri Mendeleev"},{"name":"Ivan Pavlov","emoji":"🐕","meta":["physiologist","Russia / USSR","1849–1936"],"description":"The Russian physiologist and Nobel laureate for his research on digestion, best known for his experiments on conditioned reflexes in dogs. Those experiments became the basis of a whole line of work in psychology and physiology.","fact":"Pavlov was the first Russian scientist to receive a Nobel Prize, which was awarded to him in 1904.","wiki_en":"Ivan Pavlov"},{"name":"Konstantin Tsiolkovsky","emoji":"🚀","meta":["scientist","Russia / USSR","1857–1935"],"description":"The Russian and Soviet self-taught scientist who worked out the theoretical foundations of rocketry and space flight, including the rocket equation. His writings laid the groundwork for the space programmes that followed.","fact":"After scarlet fever in childhood Tsiolkovsky almost lost his hearing, and educated himself largely on his own.","wiki_en":"Konstantin Tsiolkovsky"},{"name":"Sergei Korolev","emoji":"🛰️","meta":["designer","USSR","1907–1966"],"description":"The Soviet designer of rocket and space technology, who led the launch of the first artificial satellite of the Earth and Yuri Gagarin's flight into space. For a long time his name remained a state secret.","fact":"Korolev's name as chief designer of the space programme was kept strictly secret right up to his death in 1966.","wiki_en":"Sergei Korolev"},{"name":"Andrei Sakharov","emoji":"☢️","meta":["physicist","USSR","1921–1989"],"description":"The Soviet physicist, one of the creators of the hydrogen bomb in the USSR, who later became a well-known human rights campaigner and a Nobel Peace Prize laureate. He spoke out for human rights and for disarmament.","fact":"Sakharov received the Nobel Peace Prize in 1975, but was unable to travel to the ceremony in person.","wiki_en":"Andrei Sakharov"},{"name":"Mikhail Lomonosov","emoji":"📚","meta":["scientist","Russia","1711–1765"],"description":"The Russian polymath who contributed to chemistry, physics, astronomy and philology, and was one of the founders of the first Russian university, in Moscow. He came to science from a simple family on the northern coast.","fact":"Lomonosov left his native northern village for Moscow on foot, travelling with a convoy of fish carts, in order to study.","wiki_en":"Mikhail Lomonosov"},{"name":"Alan Turing","emoji":"💻","meta":["mathematician","United Kingdom","1912–1954"],"description":"The British mathematician who laid the theoretical foundations of computer science and made a key contribution to breaking German ciphers during the Second World War. He devised the concept of a universal computing machine, which bears his name.","fact":"The work of Turing and his team on breaking the Enigma cipher shortened the Second World War considerably, by historians' estimates.","wiki_en":"Alan Turing"},{"name":"Neil Armstrong","emoji":"🌕","meta":["astronaut","United States","1930–2012"],"description":"The American astronaut, commander of the Apollo 11 mission and the first human being to set foot on the surface of the Moon, in 1969. Before he flew in space he worked as a test pilot.","fact":"Armstrong's first words on the Moon — \"one small step for man, one giant leap for mankind\" — became one of the best-known phrases of the twentieth century.","wiki_en":"Neil Armstrong"},{"name":"Valentina Tereshkova","emoji":"👩‍🚀","meta":["cosmonaut","USSR","b. 1937"],"description":"The Soviet pilot and cosmonaut, the first woman in history to go into space: she made her flight aboard the spacecraft Vostok 6 in 1963. Before she was selected for the cosmonaut corps she was a competitive parachutist.","fact":"Tereshkova was chosen for the flight partly because of her extensive experience of parachute jumping.","wiki_en":"Valentina Tereshkova"},{"name":"Alexei Leonov","emoji":"🚀","meta":["cosmonaut","USSR","1934–2019"],"description":"The Soviet cosmonaut who was the first person in history to walk in open space, in 1965, during the flight of the spacecraft Voskhod 2. He also painted, putting space on canvas in pictures of his own.","fact":"Returning to the craft after his spacewalk, Leonov found his suit had swollen up, and had to bleed air out of it to squeeze back inside.","wiki_en":"Alexei Leonov"},{"name":"Gherman Titov","emoji":"🌍","meta":["cosmonaut","USSR","1935–2000"],"description":"The Soviet cosmonaut, the second human being in space and the first to spend more than a day there, on his flight aboard Vostok 2 in 1961. He was twenty-five at the time, and remains the youngest person ever to reach orbit.","fact":"In a day of flight Titov made more than a dozen orbits of the Earth, and was the first to complain of motion sickness in space.","wiki_en":"Gherman Titov"},{"name":"Buzz Aldrin","emoji":"🌕","meta":["astronaut","United States","b. 1930"],"description":"The American astronaut, the second person to set foot on the surface of the Moon, on the Apollo 11 mission in 1969 alongside Neil Armstrong. Before NASA he served as a military pilot and flew combat missions.","fact":"Aldrin photographed his own bootprint in the lunar soil, one of the most recognisable images of the space programme.","wiki_en":"Buzz Aldrin"},{"name":"William Shakespeare","emoji":"🎭","meta":["playwright","England","1564–1616"],"description":"The English playwright and poet, author of \"Hamlet\", \"Romeo and Juliet\" and \"Macbeth\", the plays on which world drama is built. His work has been translated into dozens of languages and is still staged in theatres all over the world.","fact":"Many expressions from Shakespeare's plays, such as \"to be or not to be\", long ago entered everyday speech as set phrases.","wiki_en":"William Shakespeare"},{"name":"Leo Tolstoy","emoji":"📖","meta":["writer","Russia","1828–1910"],"description":"The Russian writer, author of the epic novels \"War and Peace\" and \"Anna Karenina\", high points of world literature. In his later years he worked out his own religious and philosophical teaching of non-resistance to evil by force.","fact":"Tolstoy wrote and rewrote \"War and Peace\" over several years, producing a great many versions of the text.","wiki_en":"Leo Tolstoy"},{"name":"Fyodor Dostoevsky","emoji":"📕","meta":["writer","Russia","1821–1881"],"description":"The Russian writer, author of \"Crime and Punishment\", \"The Idiot\" and \"The Brothers Karamazov\", novels that go deep into human psychology. As a young man he was sentenced to death for belonging to a revolutionary circle, a sentence commuted to hard labour.","fact":"Dostoevsky stood on the scaffold waiting to be shot when, at the last moment, his sentence was changed to hard labour.","wiki_en":"Fyodor Dostoevsky"},{"name":"Alexander Pushkin","emoji":"🖋️","meta":["poet","Russia","1799–1837"],"description":"The Russian poet, author of the verse novel \"Eugene Onegin\" and of a great many poems and fairy tales, who laid the foundations of the modern Russian literary language. He died in a duel at the age of thirty-seven.","fact":"Pushkin died in a duel with Georges d'Anthès, defending his wife's honour, and the event shook the whole of Russia.","wiki_en":"Alexander Pushkin"},{"name":"Anton Chekhov","emoji":"🎭","meta":["writer and playwright","Russia","1860–1904"],"description":"The Russian writer and playwright, a master of the short story and the author of \"Three Sisters\" and \"The Cherry Orchard\". He trained as a doctor and combined medical practice with his literary work.","fact":"Chekhov combined writing with medicine all his life, calling medicine his lawful wife and literature his mistress.","wiki_en":"Anton Chekhov"},{"name":"Mark Twain","emoji":"🛶","meta":["writer","United States","1835–1910"],"description":"The American writer, author of \"The Adventures of Tom Sawyer\" and \"Adventures of Huckleberry Finn\", classics of world literature. His real name was Samuel Clemens; the pen name comes from his work as a river pilot.","fact":"The pen name Mark Twain comes from the vocabulary of river pilots and marks a river depth that is safe for navigation.","wiki_en":"Mark Twain"},{"name":"Ernest Hemingway","emoji":"🐟","meta":["writer","United States","1899–1961"],"description":"The American writer, author of the novel \"A Farewell to Arms\" and the novella \"The Old Man and the Sea\", which brought him the Pulitzer Prize. A year later he won the Nobel Prize in Literature; he is known for his spare prose and his adventurous life.","fact":"The Nobel committee's citation praised Hemingway's mastery as a storyteller, pointing among other things to \"The Old Man and the Sea\".","wiki_en":"Ernest Hemingway"},{"name":"George Orwell","emoji":"👁️","meta":["writer","United Kingdom","1903–1950"],"description":"The British writer and essayist, author of the dystopias \"1984\" and \"Animal Farm\", written as warnings against totalitarianism. Terms from his books, such as Big Brother, have entered the political vocabulary of the whole world.","fact":"The writer's real name was Eric Arthur Blair; he took his pen name from the English river Orwell.","wiki_en":"George Orwell"},{"name":"Agatha Christie","emoji":"🔍","meta":["writer","United Kingdom","1890–1976"],"description":"The British writer, author of the detective novels about the sleuths Hercule Poirot and Miss Marple. She is reckoned one of the most published authors in history, and her books have been translated into dozens of languages.","fact":"In total print runs, Christie's books are outsold in the history of publishing by little more than the Bible and Shakespeare.","wiki_en":"Agatha Christie"},{"name":"Arthur Conan Doyle","emoji":"🕵️","meta":["writer","United Kingdom","1859–1930"],"description":"The British writer who created the famous detective Sherlock Holmes and his assistant, Doctor Watson. He trained as a doctor, which helped him give his detective investigations a plausible scientific logic.","fact":"Conan Doyle grew so tired of Holmes that he once killed the character off in a story, but had to bring him back under pressure from readers.","wiki_en":"Arthur Conan Doyle"},{"name":"Stephen King","emoji":"👻","meta":["writer","United States","b. 1947"],"description":"The American writer, one of the most published authors of our time, working in horror and the supernatural. He is the author of \"The Shining\", \"It\" and \"The Green Mile\", a good many of which have been filmed.","fact":"King wrote his first published novel, \"Carrie\", after throwing the draft in the bin, from which his wife retrieved it.","wiki_en":"Stephen King"},{"name":"J. K. Rowling","emoji":"⚡","meta":["writer","United Kingdom","b. 1965"],"description":"The British writer, author of the Harry Potter novels, one of the best-selling book series in history. She began writing the first book as a single mother with very little money to her name.","fact":"The first Harry Potter book was turned down by several publishers before one of them accepted it.","wiki_en":"J. K. Rowling"},{"name":"George R. R. Martin","emoji":"🐉","meta":["writer","United States","b. 1948"],"description":"The American writer, author of the fantasy cycle \"A Song of Ice and Fire\", which became the basis of the series \"Game of Thrones\". He is known for the scale of his world and for the slow pace at which he works on the sequels.","fact":"The television adaptation, \"Game of Thrones\", overtook the plot of Martin's still unpublished books.","wiki_en":"George R. R. Martin"},{"name":"Mikhail Bulgakov","emoji":"🐈‍⬛","meta":["writer","Russia / USSR","1891–1940"],"description":"The Russian writer and playwright, author of \"The Master and Margarita\", published only decades after his death. He trained as a doctor, which shows in his early work, including \"A Young Doctor's Notebook\".","fact":"\"The Master and Margarita\" was first published in the USSR almost thirty years after Bulgakov's death, and in an abridged form.","wiki_en":"Mikhail Bulgakov"},{"name":"Aleksandr Solzhenitsyn","emoji":"⛓️","meta":["writer","USSR / Russia","1918–2008"],"description":"The Russian writer and essayist, author of \"One Day in the Life of Ivan Denisovich\" and \"The Gulag Archipelago\", based on his own experience of the camps. A Nobel laureate in literature, he spent many years in forced exile.","fact":"After \"The Gulag Archipelago\" was published in the West, Solzhenitsyn was stripped of Soviet citizenship and expelled from the country in 1974.","wiki_en":"Aleksandr Solzhenitsyn"},{"name":"Pep Guardiola","emoji":"⚽","meta":["football manager","Spain","b. 1971"],"description":"The Spanish football manager who has had extraordinary success with Barcelona, Bayern Munich and Manchester City, winning national and continental titles with each of them. He was once a player for Barcelona and for Spain.","fact":"With Manchester City, Guardiola won the treble — the English title, the FA Cup and the Champions League — in a single season.","wiki_en":"Pep Guardiola"},{"name":"Ayrton Senna","emoji":"🏎️","meta":["racing driver","Brazil","1960–1994"],"description":"The Brazilian Formula 1 driver and three-time world champion, regarded as one of the greatest racers in the history of motorsport. He died in a crash during the San Marino Grand Prix in 1994.","fact":"Senna's death on the Imola circuit in 1994 led to a sweeping overhaul of safety requirements in Formula 1.","wiki_en":"Ayrton Senna"},{"name":"Max Verstappen","emoji":"🏎️","meta":["motor racing","Netherlands","b. 1997"],"description":"The Dutch Formula 1 driver, racing for Red Bull Racing. He has been world champion several times, and is known for an aggressive, precise style of driving. He started karting as a small child and reached Formula 1 as one of the youngest drivers in history.","fact":"In 2016 Verstappen won his debut race for Red Bull, becoming the youngest ever winner of a Formula 1 race.","wiki_en":"Max Verstappen"},{"name":"Stephen Curry","emoji":"🏀","meta":["basketball","United States","b. 1988"],"description":"The American basketball player, point guard for the NBA club Golden State Warriors. He is considered one of the best long-range shooters in the history of the league and has been an NBA champion several times. His willingness to shoot from distance changed how modern basketball is played.","fact":"Curry holds the NBA record for the number of three-point shots made in a career.","wiki_en":"Stephen Curry"},{"name":"Bobby Fischer","emoji":"♟️","meta":["chess","United States","1943–2008"],"description":"The American chess player and eleventh world champion. In 1972 he beat Boris Spassky in the famous match in Reykjavik, which was covered as a symbolic confrontation of the Cold War. He later withdrew almost entirely from public appearances.","fact":"After the 1972 match Fischer all but disappeared from public chess tournaments for twenty years.","wiki_en":"Bobby Fischer"},{"name":"Irina Rodnina","emoji":"⛸️","meta":["figure skating","USSR","b. 1949"],"description":"The Soviet figure skater who competed in pairs and was a three-time Olympic champion. She won the Olympics with two different partners in succession, which happens very rarely. After her sporting career she worked as a coach and went into public life.","fact":"From 1969 Rodnina won the world pairs championship ten times in a row.","wiki_en":"Irina Rodnina"},{"name":"Vladislav Tretiak","emoji":"🥅","meta":["ice hockey","USSR","b. 1952"],"description":"The Soviet ice hockey goalkeeper, for many years with the USSR national team and the club CSKA. He is considered one of the finest goalkeepers in the history of the game, and his name is tied to the rise of the Soviet hockey school. He later worked in sports administration and coached goalkeepers in North America.","fact":"Tretiak was the first Soviet hockey player to be inducted into the Hockey Hall of Fame in Toronto.","wiki_en":"Vladislav Tretiak"},{"name":"Alexander Nevsky","emoji":"⚔️","meta":["prince","Rus","1221–1263"],"description":"The prince of early Rus who ruled Novgorod and later the grand principality of Vladimir. He is known for his victories over Swedish and German knights, among them the Battle on the Ice on Lake Peipus. The Russian Orthodox Church made him a saint.","fact":"The name Nevsky is linked to his victory on the river Neva, though historians argue about the details of that battle.","wiki_en":"Alexander Nevsky"},{"name":"Ivan the Terrible","emoji":"👑","meta":["tsar","Rus","1530–1584"],"description":"The grand prince of Moscow who became the first formally crowned Russian tsar. His reign brought an expansion of the state's territory and reforms of government, along with the oprichnina, a period of repression against part of the nobility. One of the most contradictory figures in Russian history.","fact":"Ivan IV was the first Russian ruler formally to take the title of tsar, in 1547.","wiki_en":"Ivan the Terrible"},{"name":"Dmitry Donskoy","emoji":"⚔️","meta":["prince","Rus","1350–1389"],"description":"The grand prince of Moscow and Vladimir who led the Russian army at the Battle of Kulikovo against the Horde commander Mamai. That victory became one of the symbols of the gradual freeing of the Russian lands from the Horde. He earned the name Donskoy for that battle by the Don.","fact":"By Dmitry's will the grand princedom passed to his son Vasily, for the first time without a charter from the khan of the Horde.","wiki_en":"Dmitry Donskoy"},{"name":"Kuzma Minin","emoji":"🛡️","meta":["town elder","Rus","?–1616"],"description":"The Nizhny Novgorod merchant and town elder, one of the organisers of the second people's militia during the Time of Troubles. Together with Prince Dmitry Pozharsky he raised the army that freed Moscow from the Polish-Lithuanian garrison. Monuments to him stand across Russia.","fact":"The monument to Minin and Pozharsky on Red Square in Moscow was one of the first large sculptural monuments in the country.","wiki_en":"Kuzma Minin"},{"name":"Dmitry Pozharsky","emoji":"🛡️","meta":["prince","Rus","1578–1642"],"description":"The Russian prince and commander who, together with Kuzma Minin, led the second people's militia against the Polish-Lithuanian intervention. After the liberation of Moscow in 1612 he took part in organising the new government. He is regarded as one of the key figures in ending the Time of Troubles.","fact":"The liberation of Moscow by the militia of Minin and Pozharsky in 1612 is marked in Russia as the Day of National Unity.","wiki_en":"Dmitry Pozharsky"},{"name":"Yemelyan Pugachev","emoji":"⚔️","meta":["leader of a rebellion","Russia","1742–1775"],"description":"The Don Cossack who led a major peasant revolt in Russia during the reign of Catherine II. He passed himself off as Emperor Peter III, miraculously saved, which drew a great many supporters among Cossacks and peasants. The revolt was put down and Pugachev was executed in Moscow.","fact":"The Pugachev revolt spread across territory from the Urals to the Volga region and lasted about two years.","wiki_en":"Yemelyan Pugachev"},{"name":"Alexander Suvorov","emoji":"⚔️","meta":["military commander","Russia","1730–1800"],"description":"The Russian commander and generalissimo who never lost a major battle in his military career. He wrote works of military theory, among them the book \"The Science of Victory\". His crossing of the Alps during the Swiss campaign of 1799 became especially famous.","fact":"Suvorov began his service as a rank-and-file soldier, and received the highest rank of generalissimo only at the very end of his life.","wiki_en":"Alexander Suvorov"},{"name":"Mikhail Kutuzov","emoji":"⚔️","meta":["military commander","Russia","1745–1813"],"description":"The Russian commander and field marshal who led the Russian army in the Patriotic War of 1812 against Napoleon. He commanded the troops at the Battle of Borodino and directed the strategy that drove the French army out of Russia. He died during the campaign abroad, soon after the victory.","fact":"In the wars with the Ottoman Empire, Kutuzov was twice severely wounded in the head and survived, which his doctors had hardly expected.","wiki_en":"Mikhail Kutuzov"},{"name":"Pyotr Bagration","emoji":"⚔️","meta":["general","Russia","1765–1812"],"description":"The Russian general of Georgian descent, one of the best-known commanders of the Napoleonic era. He commanded the 2nd Western Army at the start of the Patriotic War of 1812 and was mortally wounded at the Battle of Borodino. He is one of the most revered commanders of his time.","fact":"Bagration died of the wound he received at Borodino two and a half weeks after the battle.","wiki_en":"Pyotr Bagration"},{"name":"Fyodor Ushakov","emoji":"⚓","meta":["naval commander","Russia","1745–1817"],"description":"The Russian naval commander and admiral who never lost a battle at sea. He worked out new tactics for naval combat and won a string of victories over the Turkish fleet in the Black Sea. In the twenty-first century the Russian Orthodox Church canonised him as a righteous warrior saint.","fact":"Ushakov commanded the Russian squadron in the Mediterranean and took part in the capture of the French fortifications on Corfu.","wiki_en":"Fyodor Ushakov"},{"name":"Alexander III","emoji":"👑","meta":["emperor","Russia","1845–1894"],"description":"The Russian emperor who reigned from 1881 to 1894, after the murder of his father, Alexander II. His reign passed without any major war involving Russia, which earned him the historical name of the Peacemaker. He pursued a policy of strengthening autocracy and supporting domestic industry.","fact":"It was under Alexander III that construction of the Trans-Siberian Railway began in Russia.","wiki_en":"Alexander III of Russia"},{"name":"Alexander I","emoji":"👑","meta":["emperor","Russia","1777–1825"],"description":"The Russian emperor who reigned through the Napoleonic wars, including the defeat of Napoleon's army in 1812. He took part in building the Vienna system of international relations after Napoleon's fall. His sudden death in Taganrog gave rise to the legend of the elder Fyodor Kuzmich.","fact":"Alexander I came to the throne in 1801, after his father Paul I was murdered by conspirators.","wiki_en":"Alexander I of Russia"},{"name":"Alexander II","emoji":"👑","meta":["emperor","Russia","1818–1881"],"description":"The Russian emperor who went down in history as the Tsar Liberator, for abolishing serfdom in 1861. He also carried out judicial, local government and military reforms. He was killed in a terrorist attack by the People's Will in Saint Petersburg.","fact":"Alexander II survived several attempts on his life before he was killed by a bomb thrown by the People's Will in 1881.","wiki_en":"Alexander II of Russia"},{"name":"Paul I","emoji":"👑","meta":["emperor","Russia","1754–1801"],"description":"The Russian emperor, son of Catherine II, who reigned from 1796 to 1801. He changed the order of succession to the throne and carried out military and administrative reforms that angered part of the nobility. He was killed by conspirators in the Mikhailovsky Palace in Saint Petersburg.","fact":"Paul I introduced a law of succession through the male line, which stayed in force in Russia right up to 1917.","wiki_en":"Paul I of Russia"},{"name":"Rurik","emoji":"🛡️","meta":["prince","Rus","9th century"],"description":"The Varangian prince of the chronicles who, according to the \"Tale of Bygone Years\", was invited to rule in Novgorod in the ninth century. He is taken to be the founder of the Rurikid dynasty, which ruled the Russian lands until the end of the sixteenth century. His very existence is still disputed by scholars.","fact":"Historians still argue over whether Rurik was a real historical person or a composite figure of the chronicles.","wiki_en":"Rurik"},{"name":"Yaroslav the Wise","emoji":"📜","meta":["prince","Kievan Rus","c. 978–1054"],"description":"The prince of Kiev under whom the early Russian state reached a considerable political and cultural peak. In his reign the law code known as the Russian Justice was drawn up and Saint Sophia's Cathedral was built in Kiev. Through his children's marriages, Rus became related to many European ruling houses.","fact":"Yaroslav the Wise's daughters became queens of France, Norway and Hungary.","wiki_en":"Yaroslav the Wise"},{"name":"Vladimir the Great","emoji":"⛪","meta":["prince","Kievan Rus","c. 958–1015"],"description":"The prince of Kiev under whom Rus was baptised in 988, on the Byzantine model. Before he accepted Christianity he was known as the ruler who united vast East Slavic lands under his power. The Russian church honours him as a saint equal to the apostles.","fact":"The baptism of Rus under Vladimir is considered one of the key events that shaped the culture of the eastern Slavs.","wiki_en":"Vladimir the Great"},{"name":"Ivan III","emoji":"👑","meta":["grand prince","Rus","1440–1505"],"description":"The grand prince of Moscow under whom most of the Russian lands were gathered around Moscow. In 1480, after the standoff on the river Ugra, the rule of the Horde was finally thrown off. The first all-Russian law code was adopted in his reign.","fact":"It was under Ivan III that the title of Moscow's rulers first began to use the words \"sovereign of all Rus\".","wiki_en":"Ivan III of Russia"},{"name":"Boris Godunov","emoji":"👑","meta":["tsar","Russia","c. 1552–1605"],"description":"The Russian boyar and statesman who effectively ruled the country under Tsar Fyodor Ivanovich, and was then elected tsar himself in 1598. His reign fell in years of famine and the mounting Time of Troubles. The circumstances of Prince Dmitry's death in Uglich are still argued over by historians.","fact":"The death of the young prince Dmitry in Uglich set off rumours that became the ground for a series of pretenders calling themselves Dmitry.","wiki_en":"Boris Godunov"},{"name":"Felix Dzerzhinsky","emoji":"⚙️","meta":["statesman","USSR","1877–1926"],"description":"The Soviet statesman of Polish origin, founder and head of the Cheka, the first Soviet security service. He also held posts in the bodies running transport and industry in the young Soviet republic. A square in central Moscow bore his name for a long time.","fact":"The monument to Dzerzhinsky on Lubyanka Square in Moscow was taken down in 1991.","wiki_en":"Felix Dzerzhinsky"},{"name":"Lavrentiy Beria","emoji":"⚙️","meta":["statesman","USSR","1899–1953"],"description":"The Soviet statesman who ran the state security organs for a long time under Joseph Stalin. Among other things he oversaw the Soviet atomic project. After Stalin's death he was arrested during the struggle for power in the Soviet leadership and executed in 1953.","fact":"Beria was born in Abkhazia and, before his transfer to Moscow, spent several years heading the party organisation of Georgia.","wiki_en":"Lavrentiy Beria"},{"name":"Vyacheslav Molotov","emoji":"📜","meta":["statesman","USSR","1890–1986"],"description":"The Soviet statesman who served for a long time as people's commissar and then minister of foreign affairs of the USSR. His name is attached to the 1939 non-aggression treaty between the USSR and Germany, known as the Molotov–Ribbentrop Pact. The incendiary weapon called the Molotov cocktail is also named after him.","fact":"The name Molotov cocktail was coined by Finnish soldiers during the Soviet-Finnish war of 1939–1940.","wiki_en":"Vyacheslav Molotov"},{"name":"Kliment Voroshilov","emoji":"⭐","meta":["military commander","USSR","1881–1969"],"description":"The Soviet military and political figure, one of the first marshals of the Soviet Union. He was people's commissar for defence of the USSR from 1925 to 1940, and later sat in the country's highest leadership. In Soviet times many towns, factories and colleges bore his name.","fact":"In Soviet times the city of Lugansk was renamed Voroshilovgrad in his honour more than once.","wiki_en":"Kliment Voroshilov"},{"name":"Yuri Andropov","emoji":"⭐","meta":["General Secretary of the CPSU","USSR","1914–1984"],"description":"The Soviet statesman who headed the KGB of the USSR for a long time and then, from 1982, held the post of General Secretary of the CPSU Central Committee. His short rule is marked by attempts to tighten labour discipline and fight corruption. He died less than two years after his appointment to the top post.","fact":"Andropov headed the KGB for fifteen years, longer than any other head of that service.","wiki_en":"Yuri Andropov"},{"name":"Konstantin Chernenko","emoji":"⭐","meta":["General Secretary of the CPSU","USSR","1911–1985"],"description":"The Soviet statesman who held the post of General Secretary of the CPSU Central Committee from 1984 to 1985. He took the top job when he was already elderly and seriously ill, so his leadership turned out to be one of the shortest in Soviet history. After his death Mikhail Gorbachev became General Secretary.","fact":"Chernenko became General Secretary at seventy-two, the oldest person ever appointed to the post.","wiki_en":"Konstantin Chernenko"},{"name":"Alexei Kosygin","emoji":"⚙️","meta":["Chairman of the Council of Ministers","USSR","1904–1980"],"description":"The Soviet statesman who headed the Council of Ministers of the USSR for many years under Leonid Brezhnev. He is associated with the economic reform of the mid-1960s, aimed at giving enterprises more freedom of their own. He led the Soviet government for sixteen years, longer than any other Soviet premier.","fact":"The economic reform of 1965 is often called the Kosygin reform in Soviet historiography.","wiki_en":"Alexei Kosygin"},{"name":"Anastas Mikoyan","emoji":"⚙️","meta":["statesman","USSR","1895–1978"],"description":"The Soviet statesman of Armenian origin who held various senior posts under several leaders of the USSR, from Lenin to Brezhnev. His political longevity produced the saying that he went \"from Ilyich to Ilyich without a heart attack or a stroke\". He played a notable part in foreign trade and diplomacy.","fact":"At the height of the Cuban missile crisis in 1962, Mikoyan flew to Cuba for talks with its leadership.","wiki_en":"Anastas Mikoyan"},{"name":"Woodrow Wilson","emoji":"🏛️","meta":["President of the United States","United States","1856–1924"],"description":"The twenty-eighth president of the United States, who led the country through the First World War. He was the moving force behind the creation of the League of Nations and set out the Fourteen Points as the basis of the postwar order. He was awarded the Nobel Peace Prize for those efforts.","fact":"Woodrow Wilson was one of the few US presidents to receive the Nobel Peace Prize while still in office.","wiki_en":"Woodrow Wilson"},{"name":"Harry S. Truman","emoji":"🏛️","meta":["President of the United States","United States","1884–1972"],"description":"The thirty-third president of the United States, who took office after the death of Franklin Roosevelt in 1945. It was under him that atomic weapons were used against Japan and the programme of postwar aid to Europe, the Marshall Plan, was launched. He led the country in the opening years of the Cold War.","fact":"Truman had been vice-president for only a few months before he found himself leading the country.","wiki_en":"Harry S. Truman"},{"name":"Dwight D. Eisenhower","emoji":"🏛️","meta":["President of the United States","United States","1890–1969"],"description":"The American general and thirty-fourth president of the United States, who commanded the Allied forces in Europe during the Second World War. As president he pushed forward the interstate highway system and the US space programme. He led the country at the height of the Cold War.","fact":"Before his election as president, Eisenhower commanded the Allied landings in Normandy in 1944.","wiki_en":"Dwight D. Eisenhower"},{"name":"Lyndon B. Johnson","emoji":"🏛️","meta":["President of the United States","United States","1908–1973"],"description":"The thirty-sixth president of the United States, who took the post after the assassination of John F. Kennedy in 1963. Under him the civil rights acts were passed, and US involvement in the war in Vietnam grew a great deal. He pursued a programme of social reform known as the Great Society.","fact":"Johnson took the presidential oath aboard an aircraft only hours after Kennedy's assassination.","wiki_en":"Lyndon B. Johnson"},{"name":"Jimmy Carter","emoji":"🏛️","meta":["President of the United States","United States","1924–2024"],"description":"The thirty-ninth president of the United States, in office from 1977 to 1981. Under him the Camp David Accords between Egypt and Israel were signed. After his presidency he spent many years in charity work and peacemaking, for which he was awarded the Nobel Peace Prize.","fact":"Carter received the Nobel Peace Prize in 2002, more than twenty years after he left the presidency.","wiki_en":"Jimmy Carter"},{"name":"Gerald Ford","emoji":"🏛️","meta":["President of the United States","United States","1913–2006"],"description":"The thirty-eighth president of the United States, and the only head of state never elected to either the presidency or the vice-presidency by a national vote. He took the office after Richard Nixon's resignation over the Watergate scandal. He later pardoned Nixon, which drew a mixed public reaction.","fact":"At the 1976 election Ford lost to Jimmy Carter, and spent less than two and a half years in the White House.","wiki_en":"Gerald Ford"},{"name":"George H. W. Bush","emoji":"🏛️","meta":["President of the United States","United States","1924–2018"],"description":"The forty-first president of the United States, in office from 1989 to 1993. His term saw the end of the Cold War and the break-up of the Warsaw Pact, as well as Operation Desert Storm against Iraq. He had earlier headed the CIA and been vice-president under Ronald Reagan.","fact":"Before his election as president, Bush headed the Central Intelligence Agency of the United States.","wiki_en":"George H. W. Bush"},{"name":"Benjamin Franklin","emoji":"⚡","meta":["statesman","United States","1706–1790"],"description":"The American politician, scientist and publisher, one of the founding fathers of the United States. He took part in drafting the Declaration of Independence and the Constitution, and is known for his experiments with electricity, including the one with a kite. He invented the lightning rod and bifocal spectacles.","fact":"Franklin's portrait appears on the hundred-dollar bill, although he was never president of the country.","wiki_en":"Benjamin Franklin"},{"name":"Alexander Hamilton","emoji":"📜","meta":["statesman","United States","1755–1804"],"description":"The American statesman, first secretary of the treasury of the United States and one of the country's founding fathers. He laid the foundations of the federal financial system and co-wrote the collection of essays known as \"The Federalist\". He died in a duel with Vice-President Aaron Burr in 1804.","fact":"Of the eighty-five essays in \"The Federalist\", more than half were written by Hamilton himself.","wiki_en":"Alexander Hamilton"},{"name":"Ulysses S. Grant","emoji":"🏛️","meta":["President of the United States","United States","1822–1885"],"description":"The American general and eighteenth president of the United States. He commanded the Northern army in the final stage of the Civil War and accepted General Lee's surrender in 1865. As president he dealt, among other things, with the postwar reconstruction of the Southern states.","fact":"Dying of cancer, Grant wrote his memoirs to provide for his family, and finished them shortly before his death.","wiki_en":"Ulysses S. Grant"},{"name":"Henry VIII","emoji":"👑","meta":["King of England","England","1491–1547"],"description":"The king of England, known for his six marriages and for the break with the Catholic church that led to the creation of the Church of England. His reign brought a considerable strengthening of royal power and the dissolution of the monasteries. Two of his wives were executed on charges of treason.","fact":"Of Henry VIII's six wives, only the last, Catherine Parr, outlived the king.","wiki_en":"Henry VIII"},{"name":"Elizabeth I","emoji":"👑","meta":["Queen of England","England","1533–1603"],"description":"The queen of England who reigned for more than four decades and never married, which earned her the name the Virgin Queen. Her reign is called the golden age of English culture, marked by a flowering of theatre and the defeat of the Spanish Armada in 1588. The Tudor dynasty ended with her.","fact":"After Elizabeth I's death the English throne passed to the Scottish king James, who united the crowns of England and Scotland.","wiki_en":"Elizabeth I"},{"name":"Oliver Cromwell","emoji":"⚔️","meta":["Lord Protector","England","1599–1658"],"description":"The English military and political figure, a central player in the English Revolution and the Civil War. After the execution of King Charles I he led the republic as Lord Protector of England, Scotland and Ireland. After his death the monarchy in England was restored.","fact":"After the restoration of the monarchy, Cromwell's body was dug up and put through a posthumous execution.","wiki_en":"Oliver Cromwell"},{"name":"Louis XIV","emoji":"👑","meta":["King of France","France","1638–1715"],"description":"The king of France who reigned longer than any other European monarch in history, more than seven decades. Known as the Sun King, he built the palace of Versailles, which became the symbol of absolute monarchy. His reign was marked by many wars and by the spread of French influence in Europe.","fact":"Louis XIV is credited with the line \"I am the state\", though there is no reliable evidence that he ever said it.","wiki_en":"Louis XIV"},{"name":"Maximilien Robespierre","emoji":"📜","meta":["revolutionary","France","1758–1794"],"description":"The French politician, one of the central leaders of the French Revolution. He headed the Committee of Public Safety during the Jacobin dictatorship, the period known as the Terror, when thousands of people were executed. He was himself overthrown and guillotined in 1794.","fact":"Robespierre was executed in July 1794, the day after the Convention declared him an outlaw.","wiki_en":"Maximilien Robespierre"},{"name":"Marie Antoinette","emoji":"👑","meta":["Queen of France","France","1755–1793"],"description":"The French queen, wife of King Louis XVI and by birth an Austrian archduchess. During the French Revolution she became, in the eyes of her contemporaries, the symbol of the royal court's extravagance. She was guillotined in 1793, a few months after her husband.","fact":"The line \"let them eat cake\", often attributed to Marie Antoinette, is not borne out by any reliable historical source.","wiki_en":"Marie Antoinette"},{"name":"Augustus","emoji":"🏛️","meta":["Roman emperor","Ancient Rome","63 BC–AD 14"],"description":"The first Roman emperor, under whom the period of civil wars ended and the system of the principate was established. The adopted son of Julius Caesar, he brought a vast territory under his power and laid the basis of two centuries of relative stability known as the Pax Romana.","fact":"The month of August in the modern calendar is named after Augustus.","wiki_en":"Augustus"},{"name":"Mark Antony","emoji":"⚔️","meta":["Roman politician","Ancient Rome","83–30 BC"],"description":"The ancient Roman politician and commander, a comrade of Julius Caesar and, after Caesar's murder, one of the triumvirs who ruled Rome. He formed a political and personal alliance with the Egyptian queen Cleopatra. Defeated by Octavian in the naval battle of Actium, he took his own life.","fact":"Antony was married to Octavian's sister, and the breakdown of that marriage hastened the war between them.","wiki_en":"Mark Antony"},{"name":"Hannibal","emoji":"⚔️","meta":["military commander","Carthage","247–183 BC"],"description":"The Carthaginian commander, one of the best-known generals of antiquity. During the Second Punic War he crossed the Alps with an army and war elephants in order to attack Rome from northern Italy. Despite a run of major victories, the war ended in defeat for Carthage.","fact":"Hannibal fought in Italy for more than ten years, but never brought himself to lay siege to Rome itself.","wiki_en":"Hannibal"},{"name":"Spartacus","emoji":"⚔️","meta":["gladiator","Ancient Rome","c. 111–71 BC"],"description":"The Thracian who became a gladiator in ancient Rome and led the largest slave revolt against the Roman republic. Under his command the rebels held off the Roman legions successfully for several years. The revolt was eventually put down and Spartacus himself died in battle.","fact":"Very little is reliably known about Spartacus's life before the revolt; most of what survives comes from Roman historians.","wiki_en":"Spartacus"},{"name":"Konrad Adenauer","emoji":"🏛️","meta":["Chancellor of West Germany","Germany","1876–1967"],"description":"The first federal chancellor of West Germany, in the post from 1949 to 1963. He oversaw the postwar rebuilding of West Germany and its integration into Western political and economic structures. He became one of the driving forces of European integration.","fact":"Adenauer became chancellor of West Germany at the age of seventy-three and stayed in the post for fourteen years.","wiki_en":"Konrad Adenauer"},{"name":"Wilhelm II","emoji":"👑","meta":["German emperor","Germany","1859–1941"],"description":"The last German emperor and king of Prussia, who reigned until 1918. Under him Germany built up its naval power, while tensions between the European powers sharpened and led to the First World War. After Germany's defeat he abdicated and spent the rest of his life in exile in the Netherlands.","fact":"Wilhelm II was a grandson of the British queen Victoria and a cousin of King George V.","wiki_en":"Wilhelm II, German Emperor"},{"name":"Francisco Franco","emoji":"🏛️","meta":["head of state","Spain","1892–1975"],"description":"The Spanish soldier and statesman who came to power as a result of the Spanish Civil War of 1936–1939. He led the country as head of state until his death in 1975. Before he died he named Prince Juan Carlos as his successor, which led to the restoration of the monarchy.","fact":"Franco ruled Spain for almost four decades, from 1939 to 1975.","wiki_en":"Francisco Franco"},{"name":"Josip Broz Tito","emoji":"🏛️","meta":["head of state","Yugoslavia","1892–1980"],"description":"The Yugoslav statesman and soldier who led the partisan movement during the Second World War and then went on to head socialist Yugoslavia. He pursued an independent foreign policy, distancing himself from the Soviet bloc after 1948. He was one of the founders of the Non-Aligned Movement.","fact":"Tito led a single Yugoslavia for thirty-five years, and after his death the country began gradually to fall apart.","wiki_en":"Josip Broz Tito"},{"name":"Juan Perón","emoji":"🏛️","meta":["President of Argentina","Argentina","1895–1974"],"description":"The Argentine statesman who was elected president of Argentina three times. His political movement, Peronism, shaped Argentine politics for decades afterwards. He was overthrown by a military coup in 1955, but returned to power in 1973.","fact":"Perón's second wife, Eva Perón, became one of the best-known first ladies in the history of Latin America.","wiki_en":"Juan Perón"},{"name":"Simón Bolívar","emoji":"⚔️","meta":["statesman","South America","1783–1830"],"description":"The South American soldier and politician who played a key part in freeing several countries of the region from Spanish colonial rule. Bolivia is named after him, as are countless squares, streets and institutions across Latin America. He dreamed of uniting the South American states.","fact":"Bolívar took part in liberating the lands that are now Venezuela, Colombia, Ecuador, Peru and Bolivia.","wiki_en":"Simón Bolívar"},{"name":"Hirohito","emoji":"👑","meta":["Emperor of Japan","Japan","1901–1989"],"description":"The emperor of Japan who reigned longer than any other monarch in the country's history, from 1926 to 1989. His reign covered the period of Japanese expansion and the Second World War, and then the postwar recovery and Japan's turn into a symbolic constitutional monarchy. After the war he publicly renounced the status of a deity.","fact":"In Japan he came to be called Emperor Showa after his death, after the name of the era of his reign.","wiki_en":"Hirohito"},{"name":"Ho Chi Minh","emoji":"🏛️","meta":["President of Vietnam","Vietnam","1890–1969"],"description":"The Vietnamese statesman and politician who led the movement for Vietnamese independence from French colonial rule. He headed North Vietnam as president and was one of the central figures of the Vietnam War. He died a few years before the country was united under a communist government.","fact":"Vietnam's largest city, formerly Saigon, was renamed Ho Chi Minh City in his honour after the country was united.","wiki_en":"Ho Chi Minh"},{"name":"Chiang Kai-shek","emoji":"🏛️","meta":["head of state","China / Taiwan","1887–1975"],"description":"The Chinese soldier and politician, leader of the Republic of China and of the Kuomintang party. After his defeat in the civil war against the communists in 1949 he moved with his government to the island of Taiwan, where he ruled until his death. For a long time his government represented China at the UN.","fact":"Chiang Kai-shek's son, Chiang Ching-kuo, later came to lead Taiwan as well.","wiki_en":"Chiang Kai-shek"},{"name":"Haile Selassie","emoji":"👑","meta":["Emperor of Ethiopia","Ethiopia","1892–1975"],"description":"The last emperor of Ethiopia, who reigned from 1930 to 1974. He spoke from the rostrum of the League of Nations against Italian aggression and became one of the key figures in creating the Organisation of African Unity. He was overthrown by a military coup in 1974.","fact":"Haile Selassie is revered as a messiah in the Rastafarian religious movement, which began in Jamaica.","wiki_en":"Haile Selassie"},{"name":"Robert Mugabe","emoji":"🏛️","meta":["President of Zimbabwe","Zimbabwe","1924–2019"],"description":"The Zimbabwean statesman who led the country as prime minister and then as president for almost four decades after independence was declared in 1980. He first came to power as leader of the movement for liberation from British colonial rule. He was removed from power by the military in 2017.","fact":"Before he came to power Mugabe spent about ten years in prison in what was then Rhodesia.","wiki_en":"Robert Mugabe"},{"name":"Muammar Gaddafi","emoji":"🏛️","meta":["head of state","Libya","1942–2011"],"description":"The Libyan political and military figure who came to power through the military coup of 1969 and led the country for more than four decades. He pursued an independent foreign policy and wrote his programmatic \"Green Book\". He died in 2011 during the armed uprising against his rule.","fact":"In his last decades Gaddafi held no formal state office, styling himself the leader of the revolution.","wiki_en":"Muammar Gaddafi"},{"name":"Saddam Hussein","emoji":"🏛️","meta":["President of Iraq","Iraq","1937–2006"],"description":"The Iraqi statesman, president of Iraq from 1979 to 2003. During his rule the country fought a war with Iran, and then a military conflict following its invasion of Kuwait in 1990. He was overthrown by the invasion of Iraq by the United States and its allies in 2003, and later executed on the sentence of an Iraqi court.","fact":"After he was overthrown in 2003, Saddam Hussein was found hiding in an underground shelter not far from his home town.","wiki_en":"Saddam Hussein"},{"name":"Yasser Arafat","emoji":"🏛️","meta":["head of the Palestinian Authority","Palestine","1929–2004"],"description":"The Palestinian politician, long-time leader of the Palestine Liberation Organisation and first head of the Palestinian National Authority. He took part in the peace talks with Israel that led to the Oslo accords of the 1990s, for which he was awarded the Nobel Peace Prize. He remained the central figure in Palestinian politics until his death.","fact":"Arafat shared the 1994 Nobel Peace Prize with the Israeli politicians Yitzhak Rabin and Shimon Peres.","wiki_en":"Yasser Arafat"},{"name":"Golda Meir","emoji":"🏛️","meta":["Prime Minister of Israel","Israel","1898–1978"],"description":"The Israeli statesman, fourth prime minister of Israel and the first woman to hold the post. She headed the country's government during the Yom Kippur War of 1973. Before she entered Israeli politics she was born in the Russian Empire and spent her youth in the United States.","fact":"Meir left the premiership in 1974, a few months after the Yom Kippur War.","wiki_en":"Golda Meir"},{"name":"Martin Luther","emoji":"📜","meta":["theologian","Germany","1483–1546"],"description":"The German theologian and monk who began the Reformation and with it Protestantism. In 1517, by tradition, he made public his Ninety-Five Theses criticising the church's sale of indulgences. He translated the Bible into German, which had an enormous influence on the German literary language.","fact":"Luther translated the New Testament into German in a matter of months, while in hiding at Wartburg Castle.","wiki_en":"Martin Luther"},{"name":"Mother Teresa","emoji":"🙏","meta":["nun","India","1910–1997"],"description":"The Catholic nun of Albanian origin who founded an order of mercy devoted to helping the poor and the sick in Calcutta. For her charitable work she was awarded the Nobel Peace Prize in 1979. After her death she was canonised by the Catholic church.","fact":"She was born in Skopje and came to India while very young, at first to work as a schoolteacher.","wiki_en":"Mother Teresa"},{"name":"Buddha","emoji":"🧘","meta":["founder of Buddhism","India","c. 6th–5th century BC"],"description":"The Indian religious teacher known historically as Siddhartha Gautama, the founder of Buddhism. By tradition he was a prince who gave up luxury in search of spiritual enlightenment and, after long reflection, reached it under the Bodhi tree. His teaching on the path to the end of suffering became the basis of one of the world religions.","fact":"Historians cannot establish Buddha's exact dates with any certainty; different traditions give different ones.","wiki_en":"Gautama Buddha"},{"name":"Jesus Christ","emoji":"✝️","meta":["central figure of Christianity","Judea","1st century"],"description":"The central figure of Christianity, honoured as the Son of God and the Messiah. According to the gospels he preached in Judea in the first third of the first century, was executed by crucifixion and, in Christian belief, rose again on the third day. His life and teaching became the basis of one of the largest world religions.","fact":"The calendar used in most of the modern world counts its years from the presumed year of the birth of Jesus Christ.","wiki_en":"Jesus"},{"name":"Aristotle","emoji":"📜","meta":["philosopher","Ancient Greece","384–322 BC"],"description":"The ancient Greek philosopher, a pupil of Plato and the tutor of Alexander the Great. He left works on practically every field of knowledge of his time, from logic and physics to biology and politics. His philosophical system shaped European thought for more than two thousand years.","fact":"In Athens Aristotle founded his own school, the Lyceum, where lessons often took place while walking.","wiki_en":"Aristotle"},{"name":"Plato","emoji":"📜","meta":["philosopher","Ancient Greece","428–348 BC"],"description":"The ancient Greek philosopher, a pupil of Socrates and the teacher of Aristotle, founder of the philosophical school called the Academy in Athens. He set out his ideas mainly in the form of dialogues, in many of which Socrates is the chief speaker. His theory of ideal forms had an enormous influence on Western philosophy.","fact":"The Academy that Plato founded in Athens is considered one of the first institutions of higher learning in history.","wiki_en":"Plato"},{"name":"Socrates","emoji":"📜","meta":["philosopher","Ancient Greece","470–399 BC"],"description":"The ancient Greek philosopher who lived in Athens and left no writings behind: his teaching is known mainly from the works of his pupils, Plato above all. He developed the method of philosophical dialogue known as maieutics. He was sentenced to death by an Athenian court and drank hemlock.","fact":"Socrates served in the Athenian army and fought in battles of the Peloponnesian War.","wiki_en":"Socrates"},{"name":"Archimedes","emoji":"🔬","meta":["scientist","Ancient Greece","c. 287–212 BC"],"description":"The ancient Greek mathematician, physicist and engineer from Syracuse, one of the greatest scientists of antiquity. He formulated the law of buoyancy known as Archimedes' principle and made a substantial contribution to geometry and mechanics. He died during the capture of Syracuse by Roman troops.","fact":"Legend has it that Archimedes discovered his famous principle watching water displaced in a bath, and ran out into the street shouting \"Eureka!\".","wiki_en":"Archimedes"},{"name":"Pythagoras","emoji":"📐","meta":["philosopher","Ancient Greece","c. 570–495 BC"],"description":"The ancient Greek philosopher and mathematician, founder of the religious and philosophical school of the Pythagoreans. His name is traditionally attached to the theorem on the sides of a right-angled triangle, although it was known before him in other cultures. The Pythagoreans gave particular weight to numbers and musical harmony.","fact":"The Pythagoreans noticed that musical intervals can be expressed as simple ratios of string lengths.","wiki_en":"Pythagoras"},{"name":"Leonardo da Vinci","emoji":"🎨","meta":["artist and scientist","Italy","1452–1519"],"description":"The Italian artist, scientist and inventor of the Renaissance, painter of the \"Mona Lisa\" and \"The Last Supper\". He left thousands of pages of notes with sketches of flying machines, anatomical drawings and engineering ideas far ahead of his time. He is considered one of the most many-sided talents in history.","fact":"Leonardo wrote much of his notebooks in mirror writing, right to left, which made them hard for others to read.","wiki_en":"Leonardo da Vinci"},{"name":"Christopher Columbus","emoji":"⛵","meta":["navigator","Spain","1451–1506"],"description":"The navigator whose four expeditions across the Atlantic at the turn of the sixteenth century opened the American continent to Europe. He was looking for a western sea route to India with money from the Spanish crown, and never accepted that he had reached a new continent rather than Asia. His voyages began the European colonisation of America.","fact":"Columbus visited the islands of the Caribbean and the coast of South America, but never set foot in what is now the United States.","wiki_en":"Christopher Columbus"},{"name":"Ferdinand Magellan","emoji":"⛵","meta":["navigator","Portugal","c. 1480–1521"],"description":"The Portuguese navigator who led the expedition that made the first circumnavigation of the globe in history. Magellan himself died in the Philippines in a clash with local people, before the voyage was over, but one ship of his fleet did return to Spain. The voyage proved in practice that the Earth could be sailed around.","fact":"The circumnavigation was completed by a single ship, the Victoria, under the command of Juan Sebastián Elcano.","wiki_en":"Ferdinand Magellan"},{"name":"Marco Polo","emoji":"🐫","meta":["traveller","Venice","1254–1324"],"description":"The Venetian merchant and traveller who spent some two decades journeying through Asia, including the court of the Mongol khan in China. His account of those travels, written down for him by another author, introduced Europe to the distant countries of the East. For a long time it remained one of Europeans' main sources on Asia.","fact":"Marco Polo dictated the book of his travels to a fellow prisoner while he was held in a Genoese jail.","wiki_en":"Marco Polo"},{"name":"Vasco da Gama","emoji":"⛵","meta":["navigator","Portugal","c. 1460–1524"],"description":"The Portuguese navigator who led the first expedition to reach India from Europe by sea, rounding Africa. The discovery opened direct maritime trade between Europe and Asia, cutting out the middlemen. He later led two more expeditions to India.","fact":"Vasco da Gama's discovery of the sea route to India broke the monopoly of Arab and Venetian middlemen on the eastern spice trade.","wiki_en":"Vasco da Gama"},{"name":"Wolfgang Amadeus Mozart","emoji":"🎻","meta":["composer","Austria","1756–1791"],"description":"The Austrian composer, one of the greatest in the history of music, who began performing as a child prodigy at a very early age. In a short life he wrote more than six hundred works, among them the operas \"The Magic Flute\" and \"Don Giovanni\", symphonies and concertos. He died at thirty-five, leaving his \"Requiem\" unfinished.","fact":"Mozart began composing at the age of five and toured Europe giving concerts as a child prodigy.","wiki_en":"Wolfgang Amadeus Mozart"},{"name":"Ludwig van Beethoven","emoji":"🎼","meta":["composer","Germany","1770–1827"],"description":"The German composer, one of the most important in the history of music, who wrote symphonies, sonatas and chamber works. He went on composing even after he had lost almost all of his hearing as an adult. His Ninth Symphony, with its choral finale on the \"Ode to Joy\", became one of the symbols of European classical music.","fact":"Beethoven wrote some of his late works, the Ninth Symphony among them, while almost completely deaf.","wiki_en":"Ludwig van Beethoven"},{"name":"Johann Sebastian Bach","emoji":"🎹","meta":["composer","Germany","1685–1750"],"description":"The German composer and organist of the baroque era, author of an enormous number of works for organ, orchestra and choir. For years he served as cantor of St Thomas's Church in Leipzig, writing sacred music for it. In his lifetime he was known above all as a virtuoso organist; the scale of his composing was appreciated only by later generations.","fact":"Wide interest in Bach's music returned in the nineteenth century, when Felix Mendelssohn performed his \"St Matthew Passion\".","wiki_en":"Johann Sebastian Bach"},{"name":"Pyotr Tchaikovsky","emoji":"🎻","meta":["composer","Russia","1840–1893"],"description":"The Russian composer of the ballets \"Swan Lake\", \"The Sleeping Beauty\" and \"The Nutcracker\", as well as operas and symphonies. He was one of the first Russian composers to win wide international recognition in his own lifetime. He conducted at the opening of Carnegie Hall in New York in 1891.","fact":"The first production of \"Swan Lake\", in 1877, was not a success, and the ballet found its fame only after the composer's death.","wiki_en":"Pyotr Ilyich Tchaikovsky"},{"name":"Feodor Chaliapin","emoji":"🎤","meta":["opera singer","Russia","1873–1938"],"description":"The Russian opera singer with a powerful bass voice, one of the best-known opera performers of his day. He made his name in the Russian repertoire, including the title role in \"Boris Godunov\". After the revolution he emigrated and carried on a successful career abroad.","fact":"Chaliapin was made the first People's Artist of the Republic in 1918, but was later stripped of the title after he emigrated.","wiki_en":"Feodor Chaliapin"},{"name":"John Major","emoji":"🏛️","meta":["Prime Minister of the United Kingdom","United Kingdom","b. 1943"],"description":"The British politician, prime minister of the United Kingdom from 1990 to 1997, who took over the post from Margaret Thatcher. His government signed the Maastricht Treaty creating the European Union and took part in the peace process in Northern Ireland. He lost the 1997 election to Labour under Tony Blair.","fact":"Major took the job in 1990 at forty-seven, the youngest British prime minister of the century until Tony Blair replaced him in 1997.","wiki_en":"John Major"},{"name":"David Cameron","emoji":"🏛️","meta":["Prime Minister of the United Kingdom","United Kingdom","b. 1966"],"description":"The British politician, prime minister of the United Kingdom from 2010 to 2016, and the youngest in the post for almost two centuries at the time of his election. He called the 2016 referendum on the country's membership of the EU and resigned after the result, having campaigned to stay in. He later served as foreign secretary.","fact":"Cameron announced his resignation the morning after the 2016 referendum, in which a majority voted to leave the EU.","wiki_en":"David Cameron"},{"name":"Gordon Brown","emoji":"🏛️","meta":["Prime Minister of the United Kingdom","United Kingdom","b. 1951"],"description":"The British politician, prime minister of the United Kingdom from 2007 to 2010, who had spent more than ten years before that as chancellor of the exchequer in Tony Blair's government. His premiership fell during the global financial crisis of 2008. He lost the 2010 general election and stepped down as Labour leader.","fact":"In 2009 Brown hosted the G20 summit in London, devoted to fighting the global financial crisis.","wiki_en":"Gordon Brown"},{"name":"Jacques Chirac","emoji":"🏛️","meta":["President of France","France","1932–2019"],"description":"The French statesman, president of France from 1995 to 2007, who had earlier held the posts of prime minister and mayor of Paris. Under him France came out against the military invasion of Iraq in 2003. He was an energetic supporter of European integration throughout his long political career.","fact":"Chirac ran Paris as mayor for almost two decades before he became president of France.","wiki_en":"Jacques Chirac"},{"name":"Nicolas Sarkozy","emoji":"🏛️","meta":["President of France","France","b. 1955"],"description":"The French statesman, president of France from 2007 to 2012. He pursued an active foreign policy, taking part among other things in settling the conflict in Georgia in 2008. He lost the 2012 election to François Hollande and afterwards carried on in party politics.","fact":"Before his election as president, Sarkozy served in government as interior minister and as finance minister.","wiki_en":"Nicolas Sarkozy"},{"name":"François Hollande","emoji":"🏛️","meta":["President of France","France","b. 1954"],"description":"The French statesman, president of France from 2012 to 2017 and the first socialist in the post since the 1990s. During his term France faced a series of major terrorist attacks, including those in Paris in 2015. In 2017 he chose not to stand for a second term.","fact":"Hollande was the first president of the French Fifth Republic to decline to run for a second term.","wiki_en":"François Hollande"},{"name":"Gerhard Schröder","emoji":"🏛️","meta":["Chancellor of Germany","Germany","b. 1944"],"description":"The German statesman, federal chancellor of Germany from 1998 to 2005. He carried out reforms of the labour market and the welfare system known as Agenda 2010. After leaving the chancellorship he took seats on the boards of Russian energy companies.","fact":"Schröder became chancellor by replacing Helmut Kohl, who by then had led the government for sixteen years.","wiki_en":"Gerhard Schröder"},{"name":"Helmut Kohl","emoji":"🏛️","meta":["Chancellor of Germany","Germany","1930–2017"],"description":"The German statesman, federal chancellor of Germany from 1982 to 1998. He is considered one of the chief architects of German reunification in 1990, after the fall of the Berlin Wall. He also played a considerable part in European integration and in the introduction of the single European currency.","fact":"Kohl held the post of German chancellor for sixteen years in a row, longer than anyone since Otto von Bismarck.","wiki_en":"Helmut Kohl"},{"name":"Hosni Mubarak","emoji":"🏛️","meta":["President of Egypt","Egypt","1928–2020"],"description":"The Egyptian statesman, president of Egypt from 1981 to 2011, who came to power after the assassination of Anwar Sadat. His rule of almost thirty years ended with the mass protests of the Arab Spring in 2011. After his resignation he stood trial on charges connected with the suppression of the protests.","fact":"Mubarak resigned after eighteen days of mass protests on Tahrir Square in Cairo in 2011.","wiki_en":"Hosni Mubarak"},{"name":"Anwar Sadat","emoji":"🏛️","meta":["President of Egypt","Egypt","1918–1981"],"description":"The Egyptian statesman, president of Egypt from 1970 to 1981. In 1978 he signed the Camp David Accords and shared the Nobel Peace Prize with the Israeli prime minister, and in 1979 he concluded a peace treaty with Israel. He was killed in an assassination during a military parade.","fact":"Sadat was killed during a military parade in Cairo just two years after signing the peace treaty with Israel.","wiki_en":"Anwar Sadat"},{"name":"Gamal Abdel Nasser","emoji":"🏛️","meta":["President of Egypt","Egypt","1918–1970"],"description":"The Egyptian statesman and soldier, president of Egypt from 1956 to 1970. He nationalised the Suez Canal, which triggered the international crisis of 1956, and became one of the leaders of Arab nationalism. He was one of the founders of the Non-Aligned Movement.","fact":"Nasser's nationalisation of the Suez Canal in 1956 led to military intervention by Britain, France and Israel.","wiki_en":"Gamal Abdel Nasser"},{"name":"Sukarno","emoji":"🏛️","meta":["President of Indonesia","Indonesia","1901–1970"],"description":"The Indonesian statesman, the first president of Indonesia, who declared the country's independence from the Netherlands in 1945. He pursued a policy of non-alignment and was one of the organisers of the Bandung Conference of 1955. He was removed from real power after the events of 1965–1966.","fact":"Sukarno set out the five founding principles of the Indonesian state, known as Pancasila.","wiki_en":"Sukarno"},{"name":"Hugo Chávez","emoji":"🏛️","meta":["President of Venezuela","Venezuela","1954–2013"],"description":"The Venezuelan statesman, president of Venezuela from 1999 to 2013. He pursued a policy he himself called the Bolivarian Revolution, nationalising a number of sectors of the economy. He stayed in power right up to his death from cancer in 2013.","fact":"Chávez first became known after a failed attempt at a military coup in 1992, followed by about two years in prison.","wiki_en":"Hugo Chávez"},{"name":"Nicolae Ceaușescu","emoji":"🏛️","meta":["head of state","Romania","1918–1989"],"description":"The Romanian statesman who led communist Romania from 1965 to 1989. He pursued a policy of tight control over society, combined with considerable economic independence from Moscow. He was overthrown and executed along with his wife during the Romanian revolution of December 1989.","fact":"Ceaușescu was one of the few Eastern European leaders of 1989 to be overthrown by force and executed.","wiki_en":"Nicolae Ceaușescu"},{"name":"Juan Carlos I","emoji":"👑","meta":["King of Spain","Spain","b. 1938"],"description":"The king of Spain, on the throne from 1975 to 2014, after the death of Francisco Franco, who had named him as his own successor. He played a considerable part in Spain's peaceful transition to democracy, not least in resisting an attempted military coup in 1981. In 2014 he abdicated in favour of his son Felipe VI.","fact":"Juan Carlos I was proclaimed king two days after Franco's death, in November 1975.","wiki_en":"Juan Carlos I"},{"name":"Lee Hsien Loong","emoji":"🏛️","meta":["Prime Minister of Singapore","Singapore","b. 1952"],"description":"The Singaporean statesman, prime minister of Singapore from 2004 to 2024 and son of the founder of modern Singapore, Lee Kuan Yew. He continued the course of economic development and of turning the country into one of the leading financial centres of Asia. He handed the premiership to a successor in 2024.","fact":"Lee Hsien Loong led the Singapore government for twenty years in a row, longer than any Singaporean prime minister but his father.","wiki_en":"Lee Hsien Loong"},{"name":"Nicholas I","emoji":"👑","meta":["emperor","Russia","1796–1855"],"description":"The Russian emperor who reigned from 1825 to 1855, coming to the throne against the background of the Decembrist revolt. His reign is marked by a tightening of central power and of censorship, and it ended in the Crimean War, which went badly for Russia. The country's first railway was built under him.","fact":"The Decembrist revolt broke out on 14 December 1825, the day appointed for the oath of allegiance to the new emperor.","wiki_en":"Nicholas I of Russia"},{"name":"Alexander Kerensky","emoji":"🏛️","meta":["head of the Provisional Government","Russia","1881–1970"],"description":"The Russian politician, last head of the Provisional Government in 1917, which was overthrown by the Bolsheviks in October of that year. After the revolution he emigrated and spent the rest of a long life abroad, including in the United States. His name stands for the brief window between the fall of the monarchy and Bolshevik rule.","fact":"After emigrating, Kerensky lived on for more than fifty years, into the second half of the twentieth century.","wiki_en":"Alexander Kerensky"},{"name":"Grigori Rasputin","emoji":"🕯️","meta":["mystic","Russia","1869–1916"],"description":"The Russian peasant from Siberia who gained considerable influence at the court of the last Russian emperor, thanks to a reputation as a healer who could help the heir to the throne, a haemophiliac. His closeness to the imperial family angered part of the nobility and the clergy. He was killed by conspirators at the end of 1916.","fact":"Rasputin was killed by members of the Saint Petersburg nobility, and the circumstances of his death have gathered a great many legends.","wiki_en":"Grigori Rasputin"},{"name":"Vladimir Monomakh","emoji":"👑","meta":["prince","Kievan Rus","1053–1125"],"description":"The prince of Kiev, one of the last rulers of a relatively united early Rus before the period of fragmentation began. He is known for his \"Instruction to My Children\", one of the first monuments of Russian literature. Tradition ties his name to the famous Cap of Monomakh, the symbol of Russian tsarist power.","fact":"The Cap of Monomakh, symbol of the power of the Russian tsars, is linked by legend to Vladimir Monomakh, though it was made long after his reign.","wiki_en":"Vladimir II Monomakh"},{"name":"Catherine I","emoji":"👑","meta":["empress","Russia","1684–1727"],"description":"The Russian empress, second wife of Peter I, who came to the throne after his death in 1725. She was the first woman formally to rule the Russian Empire, although she came from a humble background and had no connection to the nobility before her marriage. Her reign lasted only two years.","fact":"Before her marriage to Peter I the future empress was called Marta Skavronska, and she came from the Baltic lands.","wiki_en":"Catherine I of Russia"},{"name":"Peter II","emoji":"👑","meta":["emperor","Russia","1715–1730"],"description":"The Russian emperor, grandson of Peter I, who came to the throne at the age of eleven and reigned under the guardianship of his courtiers. He was the last direct male descendant of the house of Romanov. He died of smallpox at fourteen, shortly before his planned wedding.","fact":"Under Peter II the court moved back from Petersburg to Moscow for several years.","wiki_en":"Peter II of Russia"},{"name":"Anna Ioannovna","emoji":"👑","meta":["empress","Russia","1693–1740"],"description":"The Russian empress, niece of Peter I, who reigned from 1730 to 1740. Her reign went down in history as a period of heavy foreign influence at court, above all that of her favourite, Biron. On her orders a famous Ice House was built on the Neva for the mock wedding of one of her courtiers.","fact":"Before her accession Anna Ioannovna signed the \"conditions\" limiting her power, but soon tore them up.","wiki_en":"Anna of Russia"},{"name":"Elizabeth Petrovna","emoji":"👑","meta":["empress","Russia","1709–1762"],"description":"The Russian empress, daughter of Peter I, who came to the throne through a palace coup in 1741. Under her Moscow University was founded and building of the Winter Palace began, while Russia took part in the Seven Years' War. She is known for never having signed a single death sentence in her reign.","fact":"Elizabeth carried out the coup of 1741 by turning up at night in the barracks of the Preobrazhensky grenadiers.","wiki_en":"Elizabeth of Russia"},{"name":"Charlemagne","emoji":"👑","meta":["King of the Franks","Frankish kingdom","c. 747–814"],"description":"The king of the Franks who united a large part of Western Europe under his rule and was crowned emperor of the West by the pope in 800. He encouraged the spread of learning and culture in the period known as the Carolingian Renaissance. He is considered one of the key figures in the making of medieval Europe.","fact":"According to his biographer, Charlemagne tried to learn to write in his mature years, but never really mastered it.","wiki_en":"Charlemagne"},{"name":"Justinian I","emoji":"👑","meta":["Byzantine emperor","Byzantium","c. 482–565"],"description":"The Byzantine emperor who reigned in the sixth century and set out to restore the borders of the old Roman Empire. Under him the body of Roman law known as the Code of Justinian was compiled, with an enormous influence on European law. The church of Hagia Sophia in Constantinople was also built in his reign.","fact":"Justinian's armies won back Italy and part of North Africa, but the empire could not hold those lands for long.","wiki_en":"Justinian I"},{"name":"Tamerlane","emoji":"⚔️","meta":["conqueror","Central Asia","1336–1405"],"description":"The Central Asian commander and conqueror, founder of the Timurid state with its capital at Samarkand. He fought a series of huge campaigns from India to Asia Minor, defeating among others the armies of the Golden Horde. He was a patron of building and of the arts in his capital.","fact":"Tamerlane limped on one leg from a wound taken in his youth, which is where his name, meaning Timur the Lame, comes from.","wiki_en":"Timur"},{"name":"Batu Khan","emoji":"⚔️","meta":["khan","Golden Horde","c. 1209–1255"],"description":"The Mongol khan, grandson of Genghis Khan, who led the campaign of conquest into Eastern Europe, the Russian lands included, in the thirteenth century. He founded the state known as the Golden Horde, which the Russian principalities lived under for more than two centuries. His campaign destroyed a great many early Russian towns.","fact":"The capital of Batu's state was the city of Sarai on the lower Volga, where Russian princes travelled for the charter to rule.","wiki_en":"Batu Khan"},{"name":"Joan of Arc","emoji":"⚔️","meta":["national heroine","France","1412–1431"],"description":"The French peasant girl who led the French armies at a turning point of the Hundred Years' War with England, convinced that she was acting on divine command. She lifted the siege of Orléans in 1429, which swung the war in France's favour. She was captured and burned at the stake for heresy, and canonised centuries later.","fact":"Joan of Arc was burned at the stake at the age of nineteen, and almost five hundred years later she was made a saint.","wiki_en":"Joan of Arc"},{"name":"Niccolò Machiavelli","emoji":"📜","meta":["thinker","Florence","1469–1527"],"description":"The Florentine political thinker, diplomat and writer of the Renaissance, author of \"The Prince\", a treatise on holding and strengthening power. His name became a byword for cynical, hard-headed politics, although the treatise was written as a practical handbook for rulers. He also wrote history and drama.","fact":"The adjective Machiavellian has entered many European languages as a word for unprincipled political cunning.","wiki_en":"Niccolò Machiavelli"},{"name":"Thomas More","emoji":"📜","meta":["statesman","England","1478–1535"],"description":"The English statesman, lawyer and writer, author of \"Utopia\", the book that gave its name to a whole literary genre. He served as Lord Chancellor under King Henry VIII, but was executed for refusing to recognise the king as head of the English church. The Catholic church later canonised him as a saint.","fact":"The word utopia, coined by Thomas More as the title of his book, became the common term for an unattainable ideal society.","wiki_en":"Thomas More"},{"name":"Erasmus of Rotterdam","emoji":"📜","meta":["humanist","Netherlands","c. 1466–1536"],"description":"The Dutch humanist philosopher of the Renaissance, author of the satire \"In Praise of Folly\". He prepared a critical edition of the Greek text of the New Testament and corresponded with the leading intellectuals of his day across Europe. He wanted to renew Christianity by returning to its sources, while staying inside the Catholic church.","fact":"Erasmus wrote \"In Praise of Folly\" in a matter of days, while staying in England with Thomas More.","wiki_en":"Erasmus"},{"name":"Miguel de Cervantes","emoji":"📖","meta":["writer","Spain","1547–1616"],"description":"The Spanish writer, author of \"Don Quixote\", which many consider the first modern European novel. Before he became a writer he fought in the naval battle of Lepanto, where his hand was wounded, and spent several years as a captive in Algiers. \"Don Quixote\" brought him worldwide fame after the first part appeared in 1605.","fact":"By legend Cervantes and Shakespeare died on the same day, though the difference between calendars makes that not quite accurate.","wiki_en":"Miguel de Cervantes"},{"name":"Dante Alighieri","emoji":"📖","meta":["poet","Florence","1265–1321"],"description":"The Italian poet, author of \"The Divine Comedy\", which describes a journey through hell, purgatory and paradise. He wrote in the Tuscan dialect of Italian, which played an enormous part in the making of the Italian literary language. He was exiled from his native Florence for political reasons and died in exile.","fact":"Dante never managed to return to Florence, the city that had sentenced him to exile, and died in Ravenna.","wiki_en":"Dante Alighieri"},{"name":"Johann Wolfgang von Goethe","emoji":"📖","meta":["writer","Germany","1749–1832"],"description":"The German writer, poet and scientist, author of the tragedy \"Faust\" and the novel \"The Sorrows of Young Werther\", which made him famous across Europe while he was still young. Beyond literature he worked on the natural sciences, including botany and the theory of colour. For years he served at the court of the duke of Weimar.","fact":"\"The Sorrows of Young Werther\" set off a European fashion for romantic melancholy and a wave of imitations.","wiki_en":"Johann Wolfgang von Goethe"}];
